(* --- self-wiring prologue ---------------------------------------------------- Makes the InitMqtt and InitMqttDiscovery* calls optional. Set FriendlyName at the declaration site and this block wires itself from MqttVariables on its first cyclic call, then announces itself to Home Assistant.
Deliberately in the body rather than in FB_init: it dereferences GVL members and reads the reflection instance path, and doing that during initialisation would rely on an ordering nothing enforces and the compiler cannot check. The body is the same lifecycle phase the init actions used, so this is not merely safe, it is the phase that already works today.
The wiring calls this block's own unmodified InitMqtt / InitMqttDiscovery* methods, so anything published - topics and discovery JSON alike - is produced by exactly the code that produces it today. Only the trigger moved.
Dormant while FriendlyName is empty, so existing projects and existing call sites keep working untouched.
A block wired this way MUST be called cyclically. An instance whose body never runs is now unwired and absent from Home Assistant, where the init action used to wire it regardless. Nothing warns about that. *) IF FriendlyName <> '' THEN
IF NOT InitMqttDone THEN THIS^.InitMqtt( MQTTPublishPrefix := ADR(MqttVariables.MqttPubSwitchPrefix), MQTTSubscribePrefix := ADR(MqttVariables.MqttSubSwitchPrefix), pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue), pMqttCallbackCollector := ADR(MqttVariables.collector_FB_OUTPUT_SWITCH_MQTT)); END_IF
IF InitMqttDone AND NOT initMqttDiscoveryDone THEN IF EntityType = E_MQTT_ENTITY.Light THEN THIS^.InitMqttDiscoveryAsLight( Device := ADR(MqttVariables.PLC_Device), Name := FriendlyName, RelayType := RelayType); ELSIF EntityType = E_MQTT_ENTITY.Lock THEN THIS^.InitMqttDiscoveryAsLock( Device := ADR(MqttVariables.PLC_Device), Name := FriendlyName, RelayType := RelayType); ELSIF EntityType = E_MQTT_ENTITY.Siren THEN THIS^.InitMqttDiscoveryAsSiren( Device := ADR(MqttVariables.PLC_Device), Name := FriendlyName, RelayType := RelayType); ELSIF EntityType = E_MQTT_ENTITY.Fan THEN THIS^.InitMqttDiscoveryAsFan( Device := ADR(MqttVariables.PLC_Device), Name := FriendlyName, RelayType := RelayType); ELSE (* Default, and any platform this block cannot announce as. *) THIS^.InitMqttDiscoveryAsSwitch( Device := ADR(MqttVariables.PLC_Device), Name := FriendlyName, RelayType := RelayType); END_IF END_IF
END_IF
HoldTimer(PT:= T_hold);
IF PRIO_HIGH THEN IF NOT FEEDBACK THEN PulseTrigger:=TRUE; END_IF ELSIF(PRIO_LOW AND NOT (PRIO_HIGH)) THEN IF FEEDBACK THEN PulseTrigger:=TRUE; END_IF OUT:= FALSE; ELSIF MqttHighRequest THEN IF NOT FEEDBACK THEN PulseTrigger:=TRUE; END_IF MqttHighRequest := FALSE; MqttLowRequest := FALSE; ELSIF MqttLowRequest THEN IF FEEDBACK THEN PulseTrigger:=TRUE; END_IF MqttHighRequest := FALSE; MqttLowRequest := FALSE; ELSIF(TOGGLE) THEN PulseTrigger:=TRUE; END_IF;
IF ((PreviousFeedback <> FEEDBACK) OR Startup) AND InitMqttDone THEN pMqttPublishQueue^.AddMessage( Payload := BOOL_TO_STRING(FEEDBACK), Topic := CONCAT(MqttPublishTopicPrefix^, MqttPublishTopicSuffix), Qos := MQTT.QoS.ExactlyOnce, MqttRetain := TRUE ); Startup:=FALSE; END_IF
PreviousFeedback := FEEDBACK; HoldTimer.IN := PulseTrigger; OUT := HoldTimer.Q;
PulseTrigger:=FALSE;

IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateLightEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.MQTTSubscribeTopic, PayloadOn := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadOff := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.MQTTPublishTopic);
initMqttDiscoveryDone := TRUE; END_IF

