id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateLockEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.MQTTSubscribeTopic, PayloadLock := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadUnlock := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.MQTTPublishTopic, StateUnlocked := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateLocked := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO));
initMqttDiscoveryDone := TRUE; END_IF

IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateSirenEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.MQTTSubscribeTopic, PayloadOn := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadOff := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.MQTTPublishTopic, StateOnPayload := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), StateOffPayload := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC) );
initMqttDiscoveryDone := TRUE; END_IF

