THIS^.MqttPublishTopicPrefix:=MQTTPublishPrefix;
THIS^.MQTTSubscribeTopicPrefix:=MQTTSubscribePrefix;
THIS^.pMqttPublishQueue:=pMqttPublishQueue;



SUPER^.InitBaseMqtt();
pMqttCallbackCollector^.put(instance:= THIS^); // register the FB agains the collector so mqtt events can be received

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(InitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
//check if the packet is for this FB
ELSIF CommonTypesAndFunctions.StrEquals(str1:= ADR(MQTTSubscribeTopic), str2:= Data.TopicOut) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	//now process the data
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('TRUE')) THEN
		MqttHighRequest := TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('FALSE')) THEN
		MqttLowRequest := TRUE;
	// Siren sends out a JSON
	ELSIF FIND(Data.PayloadString^, 'TRUE') > 0 THEN
		MqttHighRequest := TRUE;
	ELSIF FIND(Data.PayloadString^, 'FALSE') > 0 THEN
		MqttLowRequest := TRUE;
	END_IF
END_IF

IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateSwitchEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.MQTTSubscribeTopic, PayloadOn := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadOff := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.MQTTPublishTopic, StateOnPayload := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), StateOffPayload := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), DeviceClass := DeviceClass);
initMqttDiscoveryDone := TRUE; END_IF

IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
(* An on/off fan: no percentage or oscillation topics, because a binary output has no speed to report. A dimmer-backed fan would pass those. *) Device^.CreateFanEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.MQTTSubscribeTopic, PayloadOn := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadOff := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.MQTTPublishTopic);
initMqttDiscoveryDone := TRUE; END_IF

(* --- self-wiring prologue ----------------------------------------------------
   Makes the InitMqtt and InitMqttDiscovery* calls optional. Set FriendlyName at
   the declaration site and this block wires itself from MqttVariables on its
   first cyclic call, then announces itself to Home Assistant.

   Deliberately in the body rather than in FB_init: it dereferences GVL members
   and reads the reflection instance path, and doing that during initialisation
   would rely on an ordering nothing enforces and the compiler cannot check. The
   body is the same lifecycle phase the init actions used, so this is not merely
   safe, it is the phase that already works today.

   The wiring calls this block's own unmodified InitMqtt / InitMqttDiscovery*
   methods, so anything published - topics and discovery JSON alike - is produced
   by exactly the code that produces it today. Only the trigger moved.

   Dormant while FriendlyName is empty, so existing projects and existing call
   sites keep working untouched.

   A block wired this way MUST be called cyclically. An instance whose body never
   runs is now unwired and absent from Home Assistant, where the init action used
   to wire it regardless. Nothing warns about that.  *)
IF FriendlyName <> '' THEN

	IF NOT InitMqttDone THEN
		THIS^.InitMqtt(
			MQTTPublishPrefix := ADR(MqttVariables.MqttPubCoverPrefix),
			MQTTSubscribePrefix := ADR(MqttVariables.MqttSubCoverPrefix),
			pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue),
			pMqttCallbackCollector := ADR(MqttVariables.collector_FB_OUTPUT_COVER_MQTT));
	END_IF

	IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
		THIS^.InitMqttDiscovery(
			Device := ADR(MqttVariables.PLC_Device),
			Name := FriendlyName);
	END_IF

END_IF

(* Run the timer to not power the motors for to long *)
Cover_State_Timer(PT:=T_UD);
Cover_State_Timer.IN:=FALSE;
MU_RTrigger(CLK:=MU);
MD_RTrigger(CLK:=MD);
MU_FTrigger(CLK:=MU);
MD_FTrigger(CLK:=MD);

(* Publish once at boot so the entity has a value before the first movement.
   Deliberately 'STOPPED' rather than a derived OPEN/CLOSED: internalDir is
   PERSISTENT and does carry the last direction, but its meaning is ambiguous -
   the declaration comment says "down = false, up = true" while the logic below
   sets internalDir := FALSE after a completed upward move. 'STOPPED' is an
   honest "position unknown", and a confidently wrong OPEN or CLOSED would
   mislead automations more than no position does. *)
IF Startup AND InitMqttDone THEN
	Startup := FALSE;
	pMqttPublishQueue^.AddMessage(
		Payload := 'STOPPED',
		Topic := CONCAT(MqttPublishTopicPrefix^, MqttPublishTopicSuffix),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF

IF MU_RTrigger.Q AND InitMqttDone THEN
	pMqttPublishQueue^.AddMessage(
		Payload := 'OPENING',
		Topic := CONCAT(MqttPublishTopicPrefix^, MqttPublishTopicSuffix),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF

IF MD_RTrigger.Q AND InitMqttDone THEN
	pMqttPublishQueue^.AddMessage(
		Payload := 'CLOSING',
		Topic := CONCAT(MqttPublishTopicPrefix^, MqttPublishTopicSuffix),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF	

IF (MD_FTrigger.Q OR MU_FTrigger.Q) AND Cover_State_Timer.Q AND InitMqttDone THEN
	pMqttPublishQueue^.AddMessage(
		Payload := 'STOPPED',
		Topic := CONCAT(MqttPublishTopicPrefix^, MqttPublishTopicSuffix),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF	


IF (NOT(Cover_State_Timer.Q) AND internalUp) AND InitMqttDone THEN
	pMqttPublishQueue^.AddMessage(
		Payload := 'OPEN',
		Topic := CONCAT(MqttPublishTopicPrefix^, MqttPublishTopicSuffix),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF

IF (NOT(Cover_State_Timer.Q) AND internalDown) AND InitMqttDone THEN
	pMqttPublishQueue^.AddMessage(
		Payload := 'CLOSED',
		Topic := CONCAT(MqttPublishTopicPrefix^, MqttPublishTopicSuffix),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF


(* Check what to do *)
IF NOT(Cover_State_Timer.Q) AND internalUp THEN // don't run the motors for to long, assume we've reached end and toggle dir
	internalUp := FALSE;
	internalDown := FALSE;
	internalDir := FALSE;
ELSIF NOT(Cover_State_Timer.Q) AND internalDown THEN // don't run the motors for to long, assume we've reached end and toggle dir
	internalUp := FALSE;
	internalDown := FALSE;
	internalDir := TRUE;
ELSIF PRIO_LOCK THEN	
	internalUp := FALSE;
	internalDown := FALSE;
ELSIF PRIO_UP THEN	
	internalUp := TRUE;
	internalDown := FALSE;
	Cover_State_Timer.IN:=TRUE;
ELSIF PRIO_DN THEN	
	internalUp := FALSE;
	internalDown := TRUE;
	Cover_State_Timer.IN:=TRUE;
ELSIF TOGGLE AND (internalUp OR internalDown) THEN	// stop and toggle dir
	internalUp := FALSE;
	internalDown := FALSE;
	internalDir := NOT(internalDir);
ELSIF TOGGLE AND NOT(internalDir) THEN //move down
	internalUp := FALSE;
	internalDown := TRUE;
	Cover_State_Timer.IN:=TRUE;
ELSIF TOGGLE AND internalDir THEN //move upwards
	internalUp := TRUE;
	internalDown := FALSE;	
	Cover_State_Timer.IN:=TRUE;
ELSIF MqttRequestStop THEN
	internalUp := FALSE;
	internalDown := FALSE;
	MqttRequestStop := FALSE;
ELSIF MqttRequestOpen THEN
	internalUp := TRUE;
	internalDown := FALSE;
	MqttRequestOpen := FALSE;
	Cover_State_Timer.IN:=TRUE;;
ELSIF MqttRequestClose THEN
	internalUp := FALSE;
	internalDown := TRUE;
	MqttRequestClose := FALSE;
	Cover_State_Timer.IN:=TRUE;
END_IF

(* make sure only one motor is active at a given time *)
lock(i1 := internalUp, I2 := InternalDown, TL := T_lockout);
MU := lock.Q1;
MD := lock.Q2;

IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateCoverEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.MQTTSubscribeTopic, PayloadOpen := 'OPEN', PayloadClose := 'CLOSE', PayloadStop := 'STOP', StateTopic := THIS^.MQTTPublishTopic, StateOpen := 'OPEN', StateOpening := 'OPENING', StateClosed := 'CLOSED', StateClosing := 'CLOSING', StateStopped := 'STOPPED', DeviceClass := DeviceClass );
initMqttDiscoveryDone := TRUE; END_IF

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(InitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
//check if the packet is for this FB
ELSIF CommonTypesAndFunctions.StrEquals(str1:= ADR(MQTTSubscribeTopic), str2:= Data.TopicOut) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	//now process the data
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('STOP')) THEN			
		THIS^.MqttRequestStop:=TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('OPEN')) THEN
		THIS^.MqttRequestOpen:=TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('CLOSE')) THEN
		THIS^.MqttRequestClose:=TRUE;
	END_IF

END_IF

SUPER^._InstancePath := THIS^.InstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.MqttPublishTopicPrefix:=MQTTPublishPrefix;
THIS^.MQTTSubscribeTopicPrefix:=MQTTSubscribePrefix;

SUPER^.InitBaseMqtt();
pMqttCallbackCollector^.put(instance:= THIS^); // register the FB agains the collector so mqtt events can be received

(* --- self-wiring prologue ----------------------------------------------------
   Set FriendlyName at the declaration and this block wires itself from
   MqttVariables on its first cyclic call, then announces itself to Home
   Assistant. Same idiom, and the same reasons, as every other block here: see
   FB_OUTPUT_COVER_MQTT.

   It shares the cover prefix and the cover collector with that block. Nothing
   distinguishes the two on the wire - both are covers, and the collector asks
   every registered instance whether a message is theirs.

   A block wired this way MUST be called cyclically. An instance whose body never
   runs stays unwired and never appears in Home Assistant, and nothing warns
   about it. *)
IF FriendlyName <> '' THEN

	IF NOT InitMqttDone THEN
		THIS^.InitMqtt(
			MQTTPublishPrefix := ADR(MqttVariables.MqttPubCoverPrefix),
			MQTTSubscribePrefix := ADR(MqttVariables.MqttSubCoverPrefix),
			pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue),
			pMqttCallbackCollector := ADR(MqttVariables.collector_FB_OUTPUT_COVER_MQTT));
	END_IF

	IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
		THIS^.InitMqttDiscovery(
			Device := ADR(MqttVariables.PLC_Device),
			Name := FriendlyName);
	END_IF

END_IF

IF InitMqttDone AND (PositionTopic = '') THEN
	PositionTopic := CONCAT(THIS^.MQTTPublishTopic, '/POSITION');
	SetPositionTopic := CONCAT(THIS^.MQTTSubscribeTopic, '/POSITION');
END_IF

(* --- how much time has passed -------------------------------------------------
   The position is integrated from run time, so the length of a cycle is the one
   measurement this block cannot do without. A tick longer than MAX_TICK_MS is a
   download, a breakpoint or a task overrun rather than travel, and is dropped:
   integrating it would teleport the cover. *)
tNow := TIME();
IF NOT tValid THEN
	tValid := TRUE;
	dtMs := 0;
ELSE
	dtMs := TIME_TO_UDINT(tNow) - TIME_TO_UDINT(tLast);
	IF dtMs > MAX_TICK_MS THEN
		dtMs := 0;
	END_IF
END_IF
tLast := tNow;

(* --- integrate ---------------------------------------------------------------
   Whatever the motor did last cycle is what moved the cover, so the estimate is
   advanced before this cycle's decision is taken. *)
IF Driving = DRIVE_UP THEN
	TravelMs := TIME_TO_UDINT(T_TravelUp);
	IF TravelMs > 0 THEN
		Step := UDINT_TO_REAL(dtMs) * 100.0 / UDINT_TO_REAL(TravelMs);
		PositionReal := PositionReal + Step;
	END_IF
ELSIF Driving = DRIVE_DOWN THEN
	TravelMs := TIME_TO_UDINT(T_TravelDown);
	IF TravelMs > 0 THEN
		Step := UDINT_TO_REAL(dtMs) * 100.0 / UDINT_TO_REAL(TravelMs);
		PositionReal := PositionReal - Step;
	END_IF
END_IF

IF PositionReal > 100.0 THEN
	PositionReal := 100.0;
END_IF
IF PositionReal < 0.0 THEN
	PositionReal := 0.0;
END_IF

(* --- a held button wins -------------------------------------------------------
   A person watching the cover beats anything Home Assistant asked for, and beats
   it by abandoning the target rather than queueing behind it: releasing the
   button pins the target to wherever the cover got to, so nothing resumes.

   Both buttons at once is not a command. There is no sane guess to make. *)
IF UP AND NOT DN THEN
	ManualDrive := DRIVE_UP;
ELSIF DN AND NOT UP THEN
	ManualDrive := DRIVE_DOWN;
ELSE
	IF ManualDrive <> DRIVE_STOP THEN
		Target := PositionReal;
		Arrived := TRUE;
	END_IF
	ManualDrive := DRIVE_STOP;
END_IF

(* --- and what Home Assistant asked for ---------------------------------------
   Latched by the callback, consumed here, so a command that arrives mid-cycle is
   acted on exactly once. *)
IF MqttRequestStop THEN
	MqttRequestStop := FALSE;
	(* Hold here. The target has to be dragged to the present position or the
	   interrupted journey would resume on the next cycle - a stop that only
	   pauses is not a stop. *)
	Target := PositionReal;
	Arrived := TRUE;
ELSIF MqttRequestOpen THEN
	MqttRequestOpen := FALSE;
	Target := 100.0;
	Arrived := FALSE;
ELSIF MqttRequestClose THEN
	MqttRequestClose := FALSE;
	Target := 0.0;
	Arrived := FALSE;
ELSIF MqttRequestPosition THEN
	MqttRequestPosition := FALSE;
	Target := BYTE_TO_REAL(MqttRequestPositionPct);
	Arrived := FALSE;
END_IF

(* --- decide -------------------------------------------------------------------
   An end stop is driven into rather than stopped at: the motor keeps running for
   T_EndStop once the estimate reaches the limit, which is what makes the position
   measured there rather than integrated forever, and what lets a cover that has
   drifted find itself again. *)
(* At the limit the cover was sent to, and still being driven there. This timer
   runs on DrivingLast rather than on this cycle's decision, for the same reason
   the lockout below does. *)
AtEnd := ((Target >= 100.0) AND (PositionReal >= 100.0))
	OR ((Target <= 0.0) AND (PositionReal <= 0.0));

EndStop(IN := AtEnd AND (DrivingLast <> DRIVE_STOP), PT := T_EndStop);

IF ManualDrive <> DRIVE_STOP THEN
	Driving := ManualDrive;

ELSIF Arrived THEN
	(* Nothing outstanding. Without this the motor restarts the moment the
	   end-stop timer resets, and the cover hunts at the limit forever. *)
	Driving := DRIVE_STOP;

ELSIF Target >= 100.0 THEN
	(* Fully open is a place, not a number: the tolerance is deliberately not
	   applied here. Stopping at 98% would leave the estimate uncalibrated and the
	   entity reading STOPPED instead of OPEN, which is exactly what the first
	   bench run did. Drive to the limit, then press into it for T_EndStop. *)
	IF AtEnd AND EndStop.Q THEN
		Driving := DRIVE_STOP;
		Arrived := TRUE;
		PositionKnown := TRUE;
	ELSE
		Driving := DRIVE_UP;
	END_IF

ELSIF Target <= 0.0 THEN
	IF AtEnd AND EndStop.Q THEN
		Driving := DRIVE_STOP;
		Arrived := TRUE;
		PositionKnown := TRUE;
	ELSE
		Driving := DRIVE_DOWN;
	END_IF

ELSIF (Target - PositionReal) > BYTE_TO_REAL(Tolerance) THEN
	Driving := DRIVE_UP;

ELSIF (PositionReal - Target) > BYTE_TO_REAL(Tolerance) THEN
	Driving := DRIVE_DOWN;

ELSE
	(* Close enough. A shutter cannot be positioned finer than its own start and
	   stop time, so this is where a mid-range journey ends. *)
	Driving := DRIVE_STOP;
	Arrived := TRUE;
END_IF

IF PRIO_LOCK THEN
	Driving := DRIVE_STOP;
END_IF

(* --- lockout ------------------------------------------------------------------
   A reversing contactor must never be asked to change direction while the motor
   is still turning, so a direction change always passes through a stop of at
   least T_Lockout. Starting from standstill is not delayed. *)
IF (Driving <> DRIVE_STOP) AND (DrivingLast <> DRIVE_STOP) AND (Driving <> DrivingLast) THEN
	Driving := DRIVE_STOP;
END_IF

(* The timer runs on where the cover WAS, not on what has just been decided.
   Feeding it the decision deadlocks the block: asking to move makes IN FALSE,
   which resets the very timer that would have permitted moving, so the request
   is refused again on the next cycle and forever after. That cost a bench run,
   and the symptom was a cover that reported STOPPED at 0% no matter what was
   asked of it. *)
Lockout(IN := (DrivingLast = DRIVE_STOP), PT := T_Lockout);

IF (Driving <> DRIVE_STOP) AND (DrivingLast = DRIVE_STOP) AND NOT Lockout.Q THEN
	(* Stopped too recently to start again - the contactor gets its dead time. *)
	Driving := DRIVE_STOP;
END_IF

DrivingLast := Driving;

MU := (Driving = DRIVE_UP);
MD := (Driving = DRIVE_DOWN);
Moving := MU OR MD;
Position := REAL_TO_BYTE(PositionReal + 0.5);

(* --- state -------------------------------------------------------------------
   Moving beats resting, and an end stop beats the middle. A cover that has not
   reached a stop since power-up says STOPPED rather than guessing: the estimate
   starts at 0, which looks exactly like a shutter resting closed and is in fact
   an assumption. FB_OUTPUT_COVER_MQTT publishes STOPPED at boot for the same
   reason. *)
IF MU THEN
	State := 'OPENING';
ELSIF MD THEN
	State := 'CLOSING';
ELSIF NOT PositionKnown THEN
	State := 'STOPPED';
ELSIF Position >= 100 THEN
	State := 'OPEN';
ELSIF Position = 0 THEN
	State := 'CLOSED';
ELSE
	State := 'STOPPED';
END_IF

IF InitMqttDone AND (Startup OR (State <> PublishedState)) THEN
	PublishedState := State;
	pMqttPublishQueue^.AddMessage(
		Payload := State,
		Topic := THIS^.MQTTPublishTopic,
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE);
END_IF

(* --- position ----------------------------------------------------------------
   While moving, every PublishStep percent, so the slider tracks the shutter
   without flooding the broker. When movement ends, the exact value, because that
   is the number somebody will read off a dashboard for the next hour. *)
IF InitMqttDone THEN
	Diff := BYTE_TO_INT(Position) - BYTE_TO_INT(PublishedPosition);
	IF Diff < 0 THEN
		Diff := -Diff;
	END_IF

	IF Startup
		OR NOT PositionPublished
		OR (NOT Moving AND (Position <> PublishedPosition))
		OR (Diff >= BYTE_TO_INT(PublishStep))
	THEN
		PublishedPosition := Position;
		PositionPublished := TRUE;
		Payload := BYTE_TO_STRING(Position);
		pMqttPublishQueue^.AddMessage(
			Payload := Payload,
			Topic := PositionTopic,
			Qos := MQTT.QoS.ExactlyOnce,
			MqttRetain := TRUE);
	END_IF

	Startup := FALSE;
END_IF

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(InitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;

//the command topic: the same three payloads the older cover block takes
ELSIF CommonTypesAndFunctions.StrEquals(str1:= ADR(MQTTSubscribeTopic), str2:= Data.TopicOut) THEN
	PublishReceived := TRUE;
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('STOP')) THEN
		THIS^.MqttRequestStop := TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('OPEN')) THEN
		THIS^.MqttRequestOpen := TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('CLOSE')) THEN
		THIS^.MqttRequestClose := TRUE;
	END_IF

//and the position topic, which carries a bare number
ELSIF CommonTypesAndFunctions.StrEquals(str1:= ADR(SetPositionTopic), str2:= Data.TopicOut) THEN
	PublishReceived := TRUE;
	(* Home Assistant sends the number as text. STRING_TO_BYTE returns 0 for
	   anything it cannot parse, which is indistinguishable from a genuine
	   request to close - so an unparseable payload is dropped instead, and
	   'closed' has to be asked for as 0 or as CLOSE. *)
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('0'))
		OR (STRING_TO_BYTE(Data.PayloadString^) > 0)
	THEN
		THIS^.MqttRequestPositionPct := STRING_TO_BYTE(Data.PayloadString^);
		IF THIS^.MqttRequestPositionPct > 100 THEN
			THIS^.MqttRequestPositionPct := 100;
		END_IF
		THIS^.MqttRequestPosition := TRUE;
	END_IF
END_IF

IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
(* A different method, not extra arguments to the one FB_OUTPUT_COVER_MQTT uses: Home Assistant rejects position_topic and set_position_topic as null, so the two configs have to differ by which keys exist rather than by their values. Everything else is deliberately identical, so swapping one block for the other keeps the same behaviour for open, close and stop. *) Device^.CreateCoverEntityWithPosition( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.MQTTSubscribeTopic, PayloadOpen := 'OPEN', PayloadClose := 'CLOSE', PayloadStop := 'STOP', StateTopic := THIS^.MQTTPublishTopic, StateOpen := 'OPEN', StateOpening := 'OPENING', StateClosed := 'CLOSED', StateClosing := 'CLOSING', StateStopped := 'STOPPED', DeviceClass := DeviceClass, PositionTopic := CONCAT(THIS^.MQTTPublishTopic, '/POSITION'), SetPositionTopic := CONCAT(THIS^.MQTTSubscribeTopic, '/POSITION'), PositionOpen := 100, PositionClosed := 0);
initMqttDiscoveryDone := TRUE; END_IF

SUPER^._InstancePath := THIS^.InstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.MqttPublishTopicPrefix := MQTTPublishPrefix;
THIS^.MQTTSubscribeTopicPrefix := MQTTSubscribePrefix;

SUPER^.InitBaseMqtt();
pMqttCallbackCollector^.put(instance := THIS^); // register the FB against the collector so mqtt events can be received

(* --- self-wiring prologue ----------------------------------------------------
   Makes the InitMqtt and InitMqttDiscovery* calls optional. Set FriendlyName at
   the declaration site and this block wires itself from MqttVariables on its
   first cyclic call, then announces itself to Home Assistant.

   Deliberately in the body rather than in FB_init: it dereferences GVL members
   and reads the reflection instance path, and doing that during initialisation
   would rely on an ordering nothing enforces and the compiler cannot check. The
   body is the same lifecycle phase the init actions used, so this is not merely
   safe, it is the phase that already works today.

   The wiring calls this block's own unmodified InitMqtt / InitMqttDiscovery*
   methods, so anything published - topics and discovery JSON alike - is produced
   by exactly the code that produces it today. Only the trigger moved.

   Dormant while FriendlyName is empty, so existing projects and existing call
   sites keep working untouched.

   A block wired this way MUST be called cyclically. An instance whose body never
   runs is now unwired and absent from Home Assistant, where the init action used
   to wire it regardless. Nothing warns about that.  *)
IF FriendlyName <> '' THEN

	IF NOT InitMqttDone THEN
		THIS^.InitMqtt(
			MQTTPublishPrefix := ADR(MqttVariables.MqttPubDimmerPrefix),
			MQTTSubscribePrefix := ADR(MqttVariables.MqttSubDimmerPrefix),
			pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue),
			pMqttCallbackCollector := ADR(MqttVariables.collector_FB_DIMMER_MQTT),
			OutputDimmer := TRUE,
			Qos_Dimm := MQTT.QoS.ExactlyOnce,
			Delta_Dimm := 5);
	END_IF

	IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
		THIS^.InitMqttDiscovery(
			Device := ADR(MqttVariables.PLC_Device),
			Name := FriendlyName);
	END_IF

END_IF

IF Startup THEN
	OUT_Internal := PreviousOUT;
	Q := PreviousQ;
END_IF

IF RST THEN
	IF rst_out THEN OUT_Internal := 0; END_IF;
	Q := FALSE;
	dir := OUT_Internal > 127;
ELSIF PRIO_HIGH THEN
	Q := TRUE;
	OUT_Internal := 255;
ELSIF PRIO_LOW THEN
	Q := FALSE;
ELSIF MqttHighRequest THEN
	Q:= TRUE;
	MqttHighRequest := FALSE;
	MqttLowRequest := FALSE;
ELSIF MqttLowRequest THEN
	Q:= FALSE;
	MqttHighRequest := FALSE;
	MqttLowRequest := FALSE;
ELSIF set THEN
	OUT_Internal := val;
	Q := TRUE;
	(* set direction to up when value < 127 otherwise set dir down dir is reversed because next action will reverse again *)
	dir := OUT_Internal > 127;
ELSIF SINGLE THEN
	(* a single click reverses output Q *)
	Q := NOT Q;
	(* when dimmer is turned on we need to limit out to min and max limits *)
	IF Q THEN OUT_Internal := LIMIT(MAX(OUT_Internal,1), OUT_Internal, MAX_ON);	END_IF;
	(* set the appropriate direction of dimmer dir is reversed because next action will reverse again *)
	dir := OUT_Internal > 127;
ELSIF LONG THEN
	IF NOT Q THEN
		IF SOFT_DIMM THEN
			OUT_Internal := 1;
			dir := TRUE;
		ELSE
			OUT_Internal := LIMIT(MAX(MIN_ON,1), OUT_Internal, MAX_ON);
			DIR := OUT_Internal < 127;
		END_IF;
		Q := TRUE;
	ELSE
		(* reverse direction with every long click *)
		dir := NOT dir;
	END_IF;
END_IF;


(* while dimming is active ramp the output out up or down *)
dim(DIR := dir, e := P_LONG AND Q, TR := T_DIMM, rmp := OUT_Internal);

(* reverse direction when limits are reached *)
IF OUT_Internal = 0 THEN
	dir := TRUE;
ELSIF OUT_Internal = 255 THEN
	dir := FALSE;
END_IF;

(* limit the maximum runtime *)
IF t_ON_MAX > t#0s THEN
	t3(in := q, pt := T_ON_MAX);
	Q := Q XOR t3.Q;
END_IF;

(* Scale the internal OUT to the actual OUT *)
LIN_TRAFO(
		IN:= OUT_Internal,
		IN_MIN:= 0,
		IN_MAX:= 255,
		OUT_MIN:=OUT_LinearScaleMin,
		OUT_MAX:=OUT_LinearScaleMax
	);
OUT:= REAL_TO_WORD(LIN_TRAFO.OUT);
IF Q THEN
	Q_OUT:= OUT;
ELSE
	Q_OUT:= 0;
END_IF

IF ((ABS(BYTE_TO_INT(PreviousOUT) - BYTE_TO_INT(OUT_Internal)) >= Delta_Dimm AND OUT_Internal <> PreviousOUT) OR Startup AND OUT_Internal <> PreviousOUT OR Startup AND OutputDimmer) AND InitMqttDone THEN
	PreviousOUT:=OUT_Internal;
	pMqttPublishQueue^.AddMessage(		
		Payload := BYTE_TO_STRING(OUT_Internal),
		Topic := CONCAT(CONCAT(MqttPublishTopicPrefix^, MqttPublishTopicSuffix), '/OUT'),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF

IF (Q <> PreviousQ OR Startup) AND InitMqttDone THEN
	PreviousQ:=Q;
	pMqttPublishQueue^.AddMessage(
		Payload := BOOL_TO_STRING(Q),
		Topic := CONCAT(CONCAT(MqttPublishTopicPrefix^, MqttPublishTopicSuffix), '/Q'),
		Qos := Qos_Dimm,
		MqttRetain := TRUE
	);
END_IF

Startup:=FALSE;

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(InitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
//check if the packet is for this FB
ELSIF CONCAT(MQTTSubscribeTopic,'/Q') =  Data.TopicOut^ THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('TRUE')) THEN
		MqttHighRequest := TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('FALSE')) THEN
		MqttLowRequest := TRUE;
	END_IF;

ELSIF CONCAT(MQTTSubscribeTopic,'/OUT') =  Data.TopicOut^ THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	IF OSCAT_BASIC.IS_CC(str:= Data.PayloadString^,cmp:='0123456789.') AND THIS^.PRIO_HIGH = FALSE THEN
		THIS^.OUT_Internal:=STRING_TO_BYTE(Data.PayloadString^);
	END_IF
END_IF

THIS^.T_Debounce:=T_Debounce;
THIS^.T_Reconfig:=T_Reconfig;
THIS^.T_On_Max:=T_On_Max;
THIS^.T_Dimm_Start:=T_Dimm_Start;
THIS^.T_Dimm:=T_Dimm;
THIS^.Min_On:=Min_On;
THIS^.Max_On:=Max_On;
THIS^.Soft_Dimm:=Soft_Dimm;
THIS^.Rst_Out:=Rst_Out;
THIS^.OUT_LinearScaleMin:=OUT_LinearScaleMin;
THIS^.OUT_LinearScaleMax:=OUT_LinearScaleMax;

SUPER^._InstancePath := THIS^.InstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.MqttPublishTopicPrefix:=MQTTPublishPrefix;
THIS^.MQTTSubscribeTopicPrefix:=MQTTSubscribePrefix;
THIS^.pMqttPublishQueue:=pMqttPublishQueue;

// Dimmer specific
THIS^.OutputDimmer:=OutputDimmer;
THIS^.Qos_Dimm:=Qos_Dimm;
THIS^.Delta_Dimm:=Delta_Dimm;


SUPER^.InitBaseMqtt();
pMqttCallbackCollector^.put(instance:= THIS^); // register the FB agains the collector so mqtt events can be received

IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateLightDimmerEntity( Name := name, Id := Id, Meta := meta, CommandTopic := CONCAT(THIS^.MQTTSubscribeTopic,'/Q'), PayloadOn := 'TRUE', PayloadOff := 'FALSE', StateTopic := CONCAT(THIS^.MQTTPublishTopic,'/Q'), BrightnessCommandTopic := CONCAT(THIS^.MQTTSubscribeTopic,'/OUT'), BrightnessStateTopic := CONCAT(THIS^.MQTTPublishTopic,'/OUT'), BrightnessScale := 255);
initMqttDiscoveryDone := TRUE; END_IF

(* --- self-wiring prologue ----------------------------------------------------
   Makes the InitMqtt and InitMqttDiscovery* calls optional. Set FriendlyName at
   the declaration site and this block wires itself from MqttVariables on its
   first cyclic call, then announces itself to Home Assistant.

   Deliberately in the body rather than in FB_init: it dereferences GVL members
   and reads the reflection instance path, and doing that during initialisation
   would rely on an ordering nothing enforces and the compiler cannot check. The
   body is the same lifecycle phase the init actions used, so this is not merely
   safe, it is the phase that already works today.

   The wiring calls this block's own unmodified InitMqtt / InitMqttDiscovery*
   methods, so anything published - topics and discovery JSON alike - is produced
   by exactly the code that produces it today. Only the trigger moved.

   Dormant while FriendlyName is empty, so existing projects and existing call
   sites keep working untouched.

   A block wired this way MUST be called cyclically. An instance whose body never
   runs is now unwired and absent from Home Assistant, where the init action used
   to wire it regardless. Nothing warns about that.  *)
IF FriendlyName <> '' THEN

	IF NOT InitMqttDone THEN
		THIS^.InitMqtt(
			MQTTPublishPrefix := ADR(MqttVariables.MqttPubDimmerPrefix),
			MQTTSubscribePrefix := ADR(MqttVariables.MqttSubDimmerPrefix),
			pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue),
			pMqttCallbackCollector := ADR(MqttVariables.collector_FB_DIMMER_MQTT),
			OutputDimmer := TRUE,
			Qos_Dimm := MQTT.QoS.ExactlyOnce,
			Delta_Dimm := 5);
	END_IF

	IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
		THIS^.InitMqttDiscovery(
			Device := ADR(MqttVariables.PLC_Device),
			Name := FriendlyName);
	END_IF

END_IF

IF Startup THEN
	OUT_Internal := PreviousOUT;
	Q := PreviousQ;
END_IF

IF RST THEN
	IF rst_out THEN OUT_Internal := 0; END_IF;
	Q := FALSE;
	dir := OUT_Internal > 127;
ELSIF PRIO_HIGH THEN
	Q := TRUE;
	OUT_Internal := 255;
ELSIF PRIO_LOW THEN
	Q := FALSE;
ELSIF MqttHighRequest THEN
	Q:= TRUE;
	MqttHighRequest := FALSE;
	MqttLowRequest := FALSE;
ELSIF MqttLowRequest THEN
	Q:= FALSE;
	MqttHighRequest := FALSE;
	MqttLowRequest := FALSE;
ELSIF set THEN
	OUT_Internal := val;
	Q := TRUE;
	(* set direction to up when value < 127 otherwise set dir down dir is reversed because next action will reverse again *)
	dir := OUT_Internal > 127;
ELSIF SINGLE THEN
	(* a single click reverses output Q *)
	Q := NOT Q;
	(* when dimmer is turned on we need to limit out to min and max limits *)
	IF Q THEN OUT_Internal := LIMIT(MAX(OUT_Internal,1), OUT_Internal, MAX_ON);	END_IF;
	(* set the appropriate direction of dimmer dir is reversed because next action will reverse again *)
	dir := OUT_Internal > 127;
ELSIF LONG THEN
	IF NOT Q THEN
		IF SOFT_DIMM THEN
			OUT_Internal := 1;
			dir := TRUE;
		ELSE
			OUT_Internal := LIMIT(MAX(MIN_ON,1), OUT_Internal, MAX_ON);
			DIR := OUT_Internal < 127;
		END_IF;
		Q := TRUE;
	ELSE
		(* reverse direction with every long click *)
		dir := NOT dir;
	END_IF;
END_IF;


(* while dimming is active ramp the output out up or down *)
dim(DIR := dir, e := P_LONG AND Q, TR := T_DIMM, rmp := OUT_Internal);

(* reverse direction when limits are reached *)
IF OUT_Internal = 0 THEN
	dir := TRUE;
ELSIF OUT_Internal = 255 THEN
	dir := FALSE;
END_IF;

(* limit the maximum runtime *)
IF t_ON_MAX > t#0s THEN
	t3(in := q, pt := T_ON_MAX);
	Q := Q XOR t3.Q;
END_IF;

(* Scale the internal OUT to the actual OUT *)
LIN_TRAFO(
		IN:= OUT_Internal,
		IN_MIN:= 0,
		IN_MAX:= 255,
		OUT_MIN:=OUT_LinearScaleMin,
		OUT_MAX:=OUT_LinearScaleMax
	);
OUT:= REAL_TO_WORD(LIN_TRAFO.OUT);
IF Q THEN
	Q_OUT:= OUT;
ELSE
	Q_OUT:= 0;
END_IF

IF ((ABS(BYTE_TO_INT(PreviousOUT) - BYTE_TO_INT(OUT_Internal)) >= Delta_Dimm AND OUT_Internal <> PreviousOUT) OR Startup AND OUT_Internal <> PreviousOUT OR Startup AND OutputDimmer) AND InitMqttDone THEN
	PreviousOUT:=OUT_Internal;
	pMqttPublishQueue^.AddMessage(		
		Payload := BYTE_TO_STRING(OUT_Internal),
		Topic := CONCAT(THIS^.MQTTPublishTopic,'/OUT'),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF

IF (Q <> PreviousQ OR Startup) AND InitMqttDone THEN
	PreviousQ:=Q;
	pMqttPublishQueue^.AddMessage(
		Payload := BOOL_TO_STRING(Q),
		Topic := CONCAT(THIS^.MQTTPublishTopic,'/Q'),
		Qos := Qos_Dimm,
		MqttRetain := TRUE
	);
END_IF

Startup:=FALSE;

(* DMX specific *)
IF InitDmxDone THEN 
	IF Q THEN
		IF pDmxValues^.BUFFER[DmxChannel-1] <> OUT_Internal THEN
			pDmxValues^.BUFFER[DmxChannel-1] := OUT_Internal;
		END_IF
	ELSE 
		IF pDmxValues^.BUFFER[DmxChannel-1] <> 0 THEN
			pDmxValues^.BUFFER[DmxChannel-1] := 0;
		END_IF
	END_IF
END_IF
IF SoftDimToValue AND OUT_Internal = OUT_Target THEN // If the same, softdim to value is done
	SoftDimToValue := FALSE;
	IF SoftDimToQFalse THEN
		SoftDimToQFalse := FALSE;
		OUT_Internal := OUT_Internal_tmp;
		PreviousOUT:=OUT_Internal;
	END_IF
END_IF

IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
