IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateBinarySensorEntity( Id := id, Name := name, Meta := meta, StateTopic := THIS^.MQTTPublishTopic, PayloadOn := 'TRUE', PayloadOff := 'FALSE', DeviceClass := DeviceClass);
initMqttDiscoveryDone := TRUE; END_IF

// Valves are NC: a valve is powered - open - exactly when its own circuit asks for
// heat, and closed otherwise.
HeatRequest := FALSE;
FOR i := 1 TO VALVE_COUNT DO
	VALVE[i] := THERMOSTAT[i];
	HeatRequest := HeatRequest OR THERMOSTAT[i];
END_FOR

// Pump should only start when valves had time to switch to their correct position
PumpDelay(IN := HeatRequest,
	PT := ValveCycleTime);

// This was written as (VALVE_1 OR VALVE_2 OR ... OR VALVE_8) AND PumpDelay.Q, which
// is the same value: every VALVE[i] has just been assigned THERMOSTAT[i], so the OR
// over the valves is exactly the OR over the thermostats that HeatRequest holds.
PUMP := HeatRequest AND PumpDelay.Q;

// Detect edges on valves for MQTT messaging, and publish only the ones that moved.
// The topics are retained because Home Assistant reads them on reconnect, which is
// also why Startup forces a publish of all eight on the first cycle after init.
FOR i := 1 TO VALVE_COUNT DO
	R_Trig_Valve[i](CLK := VALVE[i]);
	F_Trig_Valve[i](CLK := VALVE[i]);

	IF ((R_Trig_Valve[i].Q OR F_Trig_Valve[i].Q) OR Startup) AND InitMqttDone THEN
		pMqttPublishQueue^.AddMessage(
			Payload := BOOL_TO_STRING(VALVE[i]),
			Topic := CONCAT(MQTTPublishTopic, CONCAT('/Valves/', VALVE_NAMES[i])),
			Qos := MQTT.QoS.ExactlyOnce,
			MqttRetain := TRUE
		);
	END_IF
END_FOR

Startup := FALSE;

SUPER^._InstancePath := THIS^.InstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.MqttPublishTopicPrefix:=MQTTPublishPrefix;
SUPER^.InitBaseMqtt();

(* --- self-wiring prologue ---------------------------------------------------- Makes the InitMqtt and InitMqttDiscovery* calls optional. Set FriendlyName at the declaration site and this block wires itself from MqttVariables on its first cyclic call, then announces itself to Home Assistant.
Deliberately in the body rather than in FB_init: it dereferences GVL members and reads the reflection instance path, and doing that during initialisation would rely on an ordering nothing enforces and the compiler cannot check. The body is the same lifecycle phase the init actions used, so this is not merely safe, it is the phase that already works today.
The wiring calls this block's own unmodified InitMqtt / InitMqttDiscovery* methods, so anything published - topics and discovery JSON alike - is produced by exactly the code that produces it today. Only the trigger moved.
Dormant while FriendlyName is empty, so existing projects and existing call sites keep working untouched.
A block wired this way MUST be called cyclically. An instance whose body never runs is now unwired and absent from Home Assistant, where the init action used to wire it regardless. Nothing warns about that. *) IF FriendlyName <> '' THEN
IF NOT InitMqttDone THEN THIS^.InitMqtt( MQTTPublishPrefix := ADR(MqttVariables.MqttPubHVACPrefix), pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue)); END_IF
IF InitMqttDone AND NOT initMqttDiscoveryDone THEN THIS^.InitMqttDiscovery( Device := ADR(MqttVariables.PLC_Device), Name := FriendlyName); END_IF
END_IF
MIN_ONTIME_TIMER(IN := IN, PT := MIN_ONTIME); MIN_ONTIME_ACTIVE := NOT(MIN_ONTIME_TIMER.Q) AND PUMP;
FB_ACTUATOR( IN := IN, MANUAL := FALSE, RST := FALSE, MIN_ONTIME := MIN_ONTIME, MIN_OFFTIME := MIN_OFFTIME, RUN_EVERY := T#0S, PUMP => PUMP, RUNTIME := RUNTIME, CYCLES := CYCLES);
//Timer to keep track of ontime
HEAT_REQUEST := PUMP;
IF ((PreviousState <> PUMP) OR Startup) AND InitMqttDone THEN pMqttPublishQueue^.AddMessage( Payload := BOOL_TO_STRING(PUMP), Topic := MQTTPublishTopic, Qos := MQTT.QoS.ExactlyOnce, MqttRetain := TRUE ); Startup:=FALSE; END_IF
PreviousState := PUMP;

