id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateBinarySensorEntity( Id := id, Name := name, Meta := meta, StateTopic := THIS^.MQTTPublishTopic, PayloadOn := 'TRUE', PayloadOff := 'FALSE', DeviceClass := DeviceClass);
initMqttDiscoveryDone := TRUE; END_IF

