THIS^.MqttPublishTopicPrefix:=MQTTPublishPrefix;
THIS^.MQTTSubscribeTopicPrefix:=MQTTSubscribePrefix;
THIS^.pMqttPublishQueue:=pMqttPublishQueue;

SUPER^.InitBaseMqtt();
pMqttCallbackCollector^.put(instance:= THIS^); // register the FB agains the collector so mqtt events can be received

IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateClimateEntity( Id := id, Name := name, Meta := meta, InitialDesiredTemperature := REAL_TO_INT(DESIRED_TEMP), CurrentTemperatureTopic := CONCAT(MQTTPublishTopic, '/TEMP'), CurrentHumidityTopic := CONCAT(MQTTPublishTopic, '/HUM'), ModeCommandTopic := CONCAT(THIS^.MQTTSubscribeTopic, '/MODE'), ModeStateTopic := CONCAT(THIS^.MQTTPublishTopic, '/MODE'), TemperatureCommandTopic := CONCAT(THIS^.MQTTSubscribeTopic, '/DESIRED_TEMP') , TemperatureStateTopic := CONCAT(THIS^.MQTTPublishTopic, '/DESIRED_TEMP'), TempStep := TempStep);
initMqttDiscoveryDone := TRUE; END_IF

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(InitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
//check if the packet is for this FB
ELSIF CONCAT(MQTTSubscribeTopic,'/DESIRED_TEMP') =  Data.TopicOut^ THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	//check if temp is numeric, then assign it;
	IF OSCAT_BASIC.IS_CC(str:= Data.PayloadString^,cmp:='0123456789.') THEN
		 // temperature requested higher then max allowed temp; set to max allowed temp
		 IF STRING_TO_REAL(Data.PayloadString^) > THIS^.MaxAllowedTemp THEN
			 THIS^.DESIRED_TEMP := THIS^.MaxAllowedTemp;		 
			 THIS^.pMqttPublishQueue^.AddMessage(
				Payload := REAL_TO_STRING(THIS^.MaxAllowedTemp),
				Topic := CONCAT(MQTTPublishTopic, '/DESIRED_TEMP'),
				Qos := MQTT.QoS.ExactlyOnce,
				MqttRetain := TRUE
			);
		 // temperature requested lower then min allowed temp: set to min allowed temp
		 ELSIF STRING_TO_REAL(Data.PayloadString^) < THIS^.MinAllowedTemp THEN
			 THIS^.DESIRED_TEMP := THIS^.MinAllowedTemp;			 
			 THIS^.pMqttPublishQueue^.AddMessage(
				Payload := REAL_TO_STRING(THIS^.MinAllowedTemp),
				Topic := CONCAT(MQTTPublishTopic, '/DESIRED_TEMP'),
				Qos := MQTT.QoS.ExactlyOnce,
				MqttRetain := TRUE
			);
		 ELSE
			 THIS^.DESIRED_TEMP := STRING_TO_REAL(Data.PayloadString^);			 
			 THIS^.pMqttPublishQueue^.AddMessage(
				Payload := Data.PayloadString^,
				Topic := CONCAT(MQTTPublishTopic, '/DESIRED_TEMP'),
				Qos := MQTT.QoS.ExactlyOnce,
				MqttRetain := TRUE
			);
		 END_IF
	END_IF

ELSIF CONCAT(MQTTSubscribeTopic,'/MODE') =  Data.TopicOut^ THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	//check if the mode is known and if so set it
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('auto')) THEN
		THIS^.HvacMode := HvacModes.auto;		
	 	THIS^.pMqttPublishQueue^.AddMessage(
			Payload := Data.PayloadString^,
			Topic := CONCAT(MQTTPublishTopic, '/MODE'),
			Qos := MQTT.QoS.ExactlyOnce,
			MqttRetain := TRUE
		);
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('off')) THEN
		THIS^.HvacMode := HvacModes.off;		
	 	THIS^.pMqttPublishQueue^.AddMessage(
			Payload := Data.PayloadString^,
			Topic := CONCAT(MQTTPublishTopic, '/MODE'),
			Qos := MQTT.QoS.ExactlyOnce,
			MqttRetain := TRUE
		);
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('heat')) THEN
		THIS^.HvacMode := HvacModes.heat;		
	 	THIS^.pMqttPublishQueue^.AddMessage(
			Payload := Data.PayloadString^,
			Topic := CONCAT(MQTTPublishTopic, '/MODE'),
			Qos := MQTT.QoS.ExactlyOnce,
			MqttRetain := TRUE
		);
	END_IF;
END_IF

THIS^.MinAllowedTemp := MinAllowedTemp;
THIS^.MaxAllowedTemp := MaxAllowedTemp;
THIS^.Hysteresis := Hysteresis;

(*Define instance names*)
InstanceNamePt := CommonTypesAndFunctions.FindLastDot(ADR(_InstancePath)) + 1;

DeviceName := LEFT(_InstancePath,find(_InstancePath, '.' )-1  ) ;

// Publish (Out);
IF	MqttPublishTopicPrefix <> 0 THEN
	THIS^.MqttPublishTopicSuffix := InstanceNamePt^;
	THIS^.MQTTPublishTopic := CONCAT(MqttPublishTopicPrefix^, THIS^.MqttPublishTopicSuffix);
END_IF

// Subscribe (In)
IF	MqttSubscribeTopicPrefix <> 0 THEN
	THIS^.MQTTSubscribeTopicSuffix := InstanceNamePt^;
	THIS^.MQTTSubscribeTopic := CONCAT(MqttSubscribeTopicPrefix^ ,THIS^.MQTTSubscribeTopicSuffix);
END_IF

(* Make truncation detectable. IEC cuts an over-long CONCAT short without any
   error, so without this the only symptom is an entity that never appears. *)
IF MqttPublishTopicPrefix <> 0 THEN
	IF LEN(MqttPublishTopicPrefix^) + LEN(THIS^.MqttPublishTopicSuffix) > MqttVariables.MQTT_TOPIC_LEN THEN
		THIS^.TopicTruncated := TRUE;
	END_IF
END_IF
IF MqttSubscribeTopicPrefix <> 0 THEN
	IF LEN(MqttSubscribeTopicPrefix^) + LEN(THIS^.MQTTSubscribeTopicSuffix) > MqttVariables.MQTT_TOPIC_LEN THEN
		THIS^.TopicTruncated := TRUE;
	END_IF
END_IF

