	initMqttDiscoveryDone := TRUE;
END_IF

(* Copy the slot out before releasing it: advancing pr is what tells a producer the
   slot may be overwritten, so it has to be the last thing that happens. *)
IF THIS^.HasMessage() THEN
	GetMessage := fifo[pr];
	pr := OSCAT_BASIC.INC1(pr,n);
END_IF;

(* Written straight into the slot: the old code staged every message through a
   single FB member, which four tasks shared as scratch space. pw is advanced only
   once all four fields are in place, and GetMessage never reads a slot while
   pr = pw, so the reader cannot observe a half-written entry.

   NOTE: that reasoning holds against the READER, not against a second WRITER. Two
   tasks in AddMessage at once still read the same pw and collide. See the block
   comment on the function block. *)
IF NOT THIS^.IsFull() THEN
	fifo[pw].Payload := Payload;
	fifo[pw].Topic := Topic;
	fifo[pw].Qos := Qos;
	fifo[pw].MqttRetain := MqttRetain;
	(* Last: advancing pw is what publishes the slot to the reader. *)
	pw := OSCAT_BASIC.INC1(pw,n);
ELSE
	DroppedCount := DroppedCount + 1;
END_IF;

//need to call publish here because of FB nums
publish(
	Topic:= ADR(LocalMqttMessage.Topic), 
	PayloadString:= ADR(LocalMqttMessage.Payload), 
	PublishAsString:= TRUE, 
	QoSIn:= LocalMqttMessage.Qos, 
	MRetain:= LocalMqttMessage.MqttRetain, 
	send:= Send);

IF NOT InitDone THEN RETURN; END_IF

IF RequestToSend THEN
	Send := TRUE;
	SendDone := FALSE;
END_IF

SendTimeout(IN := Send, PT := T#10S);

IF publish.done THEN
	 SendDone := TRUE;
	 RequestToSend:=FALSE;
	 Send:=FALSE;
	 SendTimeout(IN := FALSE);
ELSIF SendTimeout.Q THEN
	(* Give the worker back to the pool rather than losing it for good. A publish
	   that never completes - a broker dropping the connection mid-QoS-2
	   handshake, say - used to strand this instance forever. *)
	 SendErrorCount := SendErrorCount + 1;
	 SendDone := TRUE;
	 RequestToSend:=FALSE;
	 Send:=FALSE;
	 SendTimeout(IN := FALSE);
END_IF

publish.SetMqttInOut(MQTT_IN_OUT := inputMQTT_IN_OUT^);

