// Extra meta-data
IF NOT CommonTypesAndFunctions.StrEquals(str1:= ADR(Meta), str2:= ADR('')) THEN
	pBase^.meta.CharString := Meta;
END_IF

PublishEntityConfig := FALSE;
IF pStruct = 0 OR StructSize = 0 THEN
	RETURN;
END_IF

MqttTopic := CONCAT(CONCAT(CONCAT(CONCAT(THIS^.MqttDiscoveryPrefix, EntityId),'/'), Id),'/config' );

ComposeJSON(
	JSONString:= ADR(MqttJSON),
	JSONStringSize:= SIZEOF(MqttJSON),
	JSONVars:= pStruct,
	NumberOfVars:= StructSize / SIZEOF(JSONVAR),
	MaxLevel := 3,
	Rootless := TRUE,
);
ComposeJSON.Execute := TRUE;
ComposeJSON();

bStripJsonRootOk := FC_StripJsonRoot(pJson := ADR(MqttJson), uiSize := SIZEOF(MqttJson));

IF MqttJSON = '' THEN
	SendLogMessage(str:=CONCAT(CONCAT('ERROR ',Id), ' had empty MqttJSON'), instance := InstanceName);
ELSIF bStripJsonRootOk = FALSE THEN
	SendLogMessage(str:=CONCAT(CONCAT('ERROR ',Id), ' failed json root strip'), instance := InstanceName);
ELSIF NOT (MqttJSON = '') THEN
	pMqttPublishQueue^.AddMessage(
		Payload:= MqttJSON,
		Topic := MqttTopic,
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE,
	);
	SendLogMessage(str:=CONCAT(CONCAT('Added ',Id), ' as MQTT dicovery'), instance := InstanceName);
	PublishEntityConfig := TRUE;
END_IF

(* A cover with a position slider, published from its own struct.

   Deliberately a second method and a second struct rather than four optional
   parameters on CreateCoverEntity, because Home Assistant will not accept the
   fields as null. It validates set_position_topic and position_topic as strings,
   and a null fails the whole config rather than just the slider:

     Error 'string value is None for dictionary value @ data['set_position_topic']'
     when processing MQTT discovery message topic:
     'homeassistant/cover/..._FB_DO_COVER_001/config'

   which cost a working cover entity for as long as the null was published. A key
   that must not be there cannot be nulled; it has to be absent, and the way this
   project makes a key absent is a struct without it. Same reason
   MQTT_DISCOVERY_BINARY_SENSOR_ENT_CAT exists beside MQTT_DISCOVERY_BINARY_SENSOR
   rather than the category being an optional field. *)
THIS^.FillCommonFields(
	pBase := ADR(MqttDiscMsgCoverPos),
	EntityId := EntityId,
	Name := name,
	Id := Id,
	Meta := meta);

// Entity related: Specific
MqttDiscMsgCoverPos.cmd_t.CharString := CommandTopic;
MqttDiscMsgCoverPos.pl_open.CharString := PayloadOpen;
MqttDiscMsgCoverPos.pl_cls.CharString := PayloadClose;
MqttDiscMsgCoverPos.pl_stop.CharString := PayloadStop;
MqttDiscMsgCoverPos.stat_t.CharString := StateTopic;
MqttDiscMsgCoverPos.stat_open.CharString := StateOpen;
MqttDiscMsgCoverPos.stat_opening.CharString := StateOpening;
MqttDiscMsgCoverPos.stat_clsd.CharString := StateClosed;
MqttDiscMsgCoverPos.stat_closing.CharString := StateClosing;
MqttDiscMsgCoverPos.stat_stopped.CharString := StateStopped;
MqttDiscMsgCoverPos.opt.Boolean := FALSE;
MqttDiscMsgCoverPos.dev_cla.CharString := Deviceclass;

// Position
MqttDiscMsgCoverPos.pos_t.CharString := PositionTopic;
MqttDiscMsgCoverPos.set_pos_t.CharString := SetPositionTopic;
MqttDiscMsgCoverPos.pos_open.Integer := PositionOpen;
MqttDiscMsgCoverPos.pos_clsd.Integer := PositionClosed;

THIS^.PublishEntityConfig(
	pStruct := ADR(MqttDiscMsgCoverPos),
	StructSize := SIZEOF(MqttDiscMsgCoverPos),
	EntityId := EntityId,
	Id := Id);

// Returns TRUE if successful, FALSE if the string could not be parsed.
// The result is written back into the string in-place.

FC_StripJsonRoot := FALSE;

// Find actual string length by scanning for null terminator
iContentLen := 0;
FOR i := 0 TO UINT_TO_DINT(uiSize) - 1 DO
    IF pJson[i] = 0 THEN
        iContentLen := i;
        EXIT;
    END_IF
END_FOR

IF iContentLen < 5 THEN
    RETURN;
END_IF

// Find the first occurrence of ':{' (byte values 58 and 123)
bFoundStart := FALSE;
FOR i := 0 TO iContentLen - 2 DO
    IF (pJson[i] = 16#3A) AND (pJson[i + 1] = 16#7B) THEN
        iStart := i + 1; // index of the inner '{'
        bFoundStart := TRUE;
        EXIT;
    END_IF
END_FOR

IF NOT bFoundStart THEN
    RETURN;
END_IF

// Find the last '}' (byte value 125) scanning backwards
bFoundEnd := FALSE;
FOR i := iContentLen - 1 TO 0 BY -1 DO
    IF pJson[i] = 16#7D THEN
        iEnd := i;
        bFoundEnd := TRUE;
        EXIT;
    END_IF
END_FOR

IF NOT bFoundEnd THEN
    RETURN;
END_IF

// iEnd is the outer '}', the inner object runs from iStart to iEnd - 1
// Move the inner content to the beginning of the buffer
SysMemMove(pDest := pJson, pSrc := ADR(pJson[iStart]), udiCount := DINT_TO_UDINT(iEnd - iStart));

// Null-terminate
pJson[iEnd - iStart] := 0;

FC_StripJsonRoot := TRUE;

(* Nothing works until Init has supplied a transport. Failing quietly here is
   better than dereferencing a null interface on a running controller. *)
IF NOT Initialised THEN
	RETURN;
END_IF

(* The transport is serviced every cycle, not only while a step is in flight -
   it is what opens and re-opens the serial port, and it needs cycles to do that
   before anyone asks it to carry anything. *)
stepState := Transport.Service();

startupTimer(IN := TRUE, PT := StartupDelay);
silence(IN := silenceRun AND NOT restartSilence, PT := SilenceTime);
watchdog(IN := (State = 1 OR State = 2) AND NOT restartWatchdog, PT := StepTimeout);
restartSilence	:= FALSE;
restartWatchdog	:= FALSE;

CASE State OF

0:	(* ---------------------------------------------------------------- idle *)
	BusOcupied := NOT startupTimer.Q;

	IF startupTimer.Q AND devicesCount > 0 THEN
		chosen := THIS^.SelectNext();
		IF chosen >= 0 THEN
			ActiveDevice	:= chosen;
			Cursor			:= (chosen + 1) MOD devicesCount;
			BusOcupied		:= TRUE;

			(* One call, all of this device's work. *)
			StepCount := devices[chosen].BuildTransaction(pSteps := ADR(Steps));
			IF StepCount < 0 THEN
				StepCount := 0;
			ELSIF StepCount > (DINT_TO_INT(UPPER_BOUND(Steps, 1)) + 1) THEN
				StepCount := DINT_TO_INT(UPPER_BOUND(Steps, 1)) + 1;
			END_IF

			StepIndex	:= 0;
			StepsRun	:= 0;
			Failures	:= 0;

			IF StepCount = 0 THEN
				(* Withdrew after asking. Release rather than hold the bus. *)
				State := 4;
			ELSE
				restartWatchdog := TRUE;
				State := 1;
			END_IF
		END_IF
	END_IF

1:	(* ------------------------------------------------- hand the step over *)
	BusOcupied := TRUE;
	IF Transport.Start(pStep := ADR(Steps[StepIndex])) THEN
		State := 2;
	ELSIF watchdog.Q THEN
		(* Refused for as long as the watchdog allows: the port is down, or the
		   function code is one this transport will not frame. Either way the
		   step is over - retrying forever would wedge the whole bus. *)
		Watchdogs := Watchdogs + 1;
		THIS^.FinishStep(Failed := TRUE, pData := 0, Count := 0);
	END_IF

2:	(* ------------------------------------------------------ wait it out *)
	BusOcupied := TRUE;
	IF stepState = RS485_StepState.OK THEN
		THIS^.FinishStep(Failed := FALSE,
		                 pData := Transport.ReadBuffer(),
		                 Count := Transport.Registers());
	ELSIF stepState = RS485_StepState.FAILED THEN
		THIS^.FinishStep(Failed := TRUE, pData := Transport.ReadBuffer(), Count := 0);
	ELSIF watchdog.Q THEN
		Watchdogs := Watchdogs + 1;
		THIS^.FinishStep(Failed := TRUE, pData := 0, Count := 0);
	END_IF

3:	(* ------------------------ silence between two steps of one transaction *)
	(* The bus is NOT released here. This gap is the inter-frame silence RTU
	   needs; letting another device in would break the guarantee that makes a
	   read-after-write worth doing. *)
	BusOcupied := TRUE;
	IF silence.Q THEN
		silenceRun		:= FALSE;
		restartWatchdog	:= TRUE;
		State			:= 1;
	END_IF

4:	(* ------------------------------------------------------------- release *)
	BusOcupied := TRUE;
	devices[ActiveDevice].OnTransactionDone(StepsRun := StepsRun, Failures := Failures);
	Transactions	:= Transactions + 1;
	ActiveDevice	:= -1;
	silenceRun		:= TRUE;
	restartSilence	:= TRUE;
	State			:= 5;

5:	(* --------------------------------- silence before anyone else may start *)
	BusOcupied := TRUE;
	IF silence.Q THEN
		silenceRun	:= FALSE;
		State		:= 0;
	END_IF

END_CASE

(* One step is over, for whatever reason. Report it, then decide whether the
   transaction continues. *)

devices[ActiveDevice].OnStepResult(StepIndex := StepIndex,
                                   Failed := Failed,
                                   pData := pData,
                                   Count := Count);

StepsRun		:= StepsRun + 1;
StepsExecuted	:= StepsExecuted + 1;

IF Failed THEN
	Failures		:= Failures + 1;
	StepFailures	:= StepFailures + 1;
END_IF

IF Failed AND Steps[StepIndex].AbortOnError THEN
	(* The step that everything after it depended on. Skipping the rest is the
	   point: a read-back published after a failed write would report a value
	   the device never took. *)
	State := 4;

ELSE
	StepIndex := StepIndex + 1;
	IF StepIndex >= StepCount THEN
		State := 4;
	ELSE
		silenceRun		:= TRUE;
		restartSilence	:= TRUE;
		State			:= 3;
	END_IF
END_IF

(* Registration order no longer decides who is served first - that is the point
   of the cursor - so devices can be registered in whatever order reads best at
   the call site. *)
IF devicesCount <= DINT_TO_INT(UPPER_BOUND(devices, 1)) THEN
	devices[devicesCount]	:= device;
	devicesCount			:= devicesCount + 1;
	RegisterDevice			:= TRUE;
ELSE
	RegisterDevice := FALSE;
END_IF

THIS^.Transport := Transport;

(* Zero means "keep the default", so a call site can supply only what it cares
   about and the block still starts with sane timings. *)
IF StartupDelay > T#0S THEN
	THIS^.StartupDelay := StartupDelay;
END_IF
IF SilenceTime > T#0S THEN
	THIS^.SilenceTime := SilenceTime;
END_IF
IF StepTimeout > T#0S THEN
	THIS^.StepTimeout := StepTimeout;
END_IF

Initialised := TRUE;

IF Index >= 0 AND Index < devicesCount THEN
	GetDevice := devices[Index];
END_IF

(* Nothing configured, nothing to hold the bus off for. A commissioner that was
   never Init'ed must not stop a bus from working - the failure mode of the
   alternative is a silent bus with no error to show for it. *)
IF NOT Initialised THEN
	Done := TRUE;
	RETURN;
END_IF

CASE State OF

0:	IF NOT Enabled OR pController = 0 THEN
		State := 90;
	ELSE
		DeviceIdx := 0;
		State := 1;
	END_IF

1:	(* Ask the next registered device. This is the whole of what makes the sequence
	   device-agnostic: what to probe, what to write and which rates are worth
	   trying all come back from the device itself. *)
	IF DeviceIdx >= pController^.DeviceCount() THEN
		State := 90;
	ELSE
		device := pController^.GetDevice(Index := DeviceIdx);
		Asked := Asked + 1;
		IF device.GetCommissioning(BusBaudrate := BusBaudrate, pRequest := ADR(Request)) THEN
			Requested		:= Requested + 1;
			BaudIdx			:= 0;
			StopIdx			:= 0;
			FoundBaud		:= 0;
			FoundStop		:= 0;
			MaxRx			:= 0;
			MaxRxBaud		:= 0;
			MaxRxStop		:= 0;
			DeviceProbes	:= 0;
			DeviceWritten	:= FALSE;
			State			:= 2;
		ELSE
			State := 80;
		END_IF
	END_IF

2:	(* Bring the bus to the setting under test. Short timeouts: a probe that is
	   going to fail should fail quickly, because most of them will. *)
	IF Transport.Retune(
			Baudrate		:= Request.Bauds[BaudIdx],
			StopBitsRaw		:= Request.StopBits[StopIdx],
			ReplyTimeout	:= T#200MS,
			GapTime			:= T#20MS) THEN
		Delay(IN := FALSE);
		State := 3;
	ELSE
		(* A transport that cannot be re-tuned cannot be swept. Give up rather than
		   probe at a setting only believed to be applied. *)
		State := 70;
	END_IF

3:	(* Let Service actually re-open the port before anything is sent into it. *)
	Delay(IN := TRUE, PT := T#200MS);
	Transport.Service();
	IF Delay.Q THEN
		Delay(IN := FALSE);
		State := 4;
	END_IF

4:	(* Probe. The point is not what comes back - it is that something did. *)
	Step.DeviceId		:= Request.DeviceId;
	Step.FunctionCode	:= Request.ProbeFunction;
	Step.Address		:= Request.ProbeAddress;
	Step.Quantity		:= Request.ProbeQuantity;
	Step.AbortOnError	:= FALSE;

	Delay(IN := TRUE, PT := T#2S);
	IF Transport.Start(pStep := ADR(Step)) THEN
		Delay(IN := FALSE);
		DeviceProbes	:= DeviceProbes + 1;
		Probes			:= Probes + 1;
		State			:= 5;
	ELSIF Delay.Q THEN
		(* Port never opened at this setting. A miss, not a fault. *)
		Delay(IN := FALSE);
		State := 6;
	END_IF

5:	Outcome := Transport.Service();
	IF Outcome <> RS485_StepState.BUSY THEN
		(* Bytes arriving at all is the useful signal when none of them frame: it
		   separates a device that is present and mis-configured from a bus with
		   nothing on it, which is the difference between sweeping on and going to
		   look at the wiring. *)
		IF Transport.LastRxCount() > MaxRx THEN
			MaxRx		:= Transport.LastRxCount();
			MaxRxBaud	:= Request.Bauds[BaudIdx];
			MaxRxStop	:= Request.StopBits[StopIdx];
		END_IF
		IF Outcome = RS485_StepState.OK THEN
			FoundBaud	:= Request.Bauds[BaudIdx];
			FoundStop	:= Request.StopBits[StopIdx];
			State		:= 7;
		ELSE
			State := 6;
		END_IF
	END_IF

6:	(* Next rate; when the rates run out, the next framing; when both run out, this
	   device cannot be reached at any setting it named. *)
	IF BaudIdx < Request.BaudCount - 1 THEN
		BaudIdx	:= BaudIdx + 1;
		State	:= 2;
	ELSIF StopIdx < Request.StopCount - 1 THEN
		BaudIdx		:= 0;
		StopIdx		:= StopIdx + 1;
		State		:= 2;
	ELSE
		State := 70;
	END_IF

7:	(* Found it. Already where it belongs? Then there is nothing to write, which is
	   the normal outcome on every boot after the first. *)
	IF FoundBaud = BusBaudrate THEN
		State := 70;
	ELSE
		State := 8;
	END_IF

8:	(* Write the value the device asked for into the register it named. Nothing here
	   knows what that value means. *)
	Step.DeviceId		:= Request.DeviceId;
	Step.FunctionCode	:= Request.WriteFunction;
	Step.Address		:= Request.WriteAddress;
	Step.Quantity		:= 1;
	Step.Data[0]		:= Request.WriteValue;
	Step.AbortOnError	:= FALSE;

	Delay(IN := TRUE, PT := T#2S);
	IF Transport.Start(pStep := ADR(Step)) THEN
		Delay(IN := FALSE);
		DeviceWritten	:= TRUE;
		Written			:= Written + 1;
		State			:= 9;
	ELSIF Delay.Q THEN
		Delay(IN := FALSE);
		State := 70;
	END_IF

9:	(* The acknowledgement comes back at the NEW setting and this end will not hear
	   it, so the outcome is deliberately ignored: a failure here is the expected
	   result of success, and nothing may retry on it. *)
	IF Transport.Service() <> RS485_StepState.BUSY THEN
		State := 70;
	END_IF

70:	(* Put the bus back the way the program configured it, whatever happened. *)
	Transport.RestoreTuning();
	Delay(IN := FALSE);
	State := 71;

71:	Delay(IN := TRUE, PT := T#500MS);
	Transport.Service();
	IF Delay.Q THEN
		Delay(IN := FALSE);
		State := 72;
	END_IF

72:	(* Publish the outcome, retained, so it can be read off the broker at any time.
	   The alternative is an online debug session, and on this hardware that is the
	   least reliable thing in the chain - the runtime drops the session long before
	   it drops MQTT. A commissioning result nobody can read is not a result.

	   Built up a piece at a time rather than nested: CONCAT takes exactly two
	   arguments, and a seven-deep nest of it is unreadable even when correct. *)
	Report := CONCAT('probes=', UDINT_TO_STRING(DeviceProbes));
	Report := CONCAT(Report, ' found=');
	Report := CONCAT(Report, UDINT_TO_STRING(FoundBaud));
	Report := CONCAT(Report, '/');
	Report := CONCAT(Report, BYTE_TO_STRING(FoundStop));
	Report := CONCAT(Report, ' maxrx=');
	Report := CONCAT(Report, UDINT_TO_STRING(MaxRx));
	Report := CONCAT(Report, ' at=');
	Report := CONCAT(Report, UDINT_TO_STRING(MaxRxBaud));
	Report := CONCAT(Report, '/');
	Report := CONCAT(Report, BYTE_TO_STRING(MaxRxStop));
	Report := CONCAT(Report, ' written=');
	Report := CONCAT(Report, BOOL_TO_STRING(DeviceWritten));
	LastReport := Report;

	IF pQueue <> 0 AND pTopicPrefix <> 0 AND Request.ReportTopic <> '' THEN
		pQueue^.AddMessage(
			Payload := Report,
			Topic := CONCAT(pTopicPrefix^, Request.ReportTopic),
			Qos := MQTT.QoS.ExactlyOnce,
			MqttRetain := TRUE);
	END_IF

	State := 80;

80:	DeviceIdx	:= DeviceIdx + 1;
	State		:= 1;

90:	(* Nothing left to do. The bus is on its own settings and the scheduler can
	   have it. *)
	Done := TRUE;

END_CASE

THIS^.Transport		:= Transport;
THIS^.pController	:= pController;
THIS^.BusBaudrate	:= BusBaudrate;
THIS^.pQueue		:= pMqttPublishQueue;
THIS^.pTopicPrefix	:= MqttPublishPrefix;
THIS^.Enabled		:= Enable;

Initialised := TRUE;

(* Queues a single-register write for the next time this device is granted the
   bus. HasWork reports COMMAND while one is pending, so it goes ahead of routine
   polling on this and every other device.

   Registers worth knowing, from the DFRobot reference:
     16#04  baud rate    0..9 = 2400, 4800, 9600, 19200, 38400, 57600,
                         115200, 230400, 460800, 921600
     16#1A  slave id     16#00..16#FE
     16#08  measurement interval, 1..1000 ms
     16#36  measurement mode  1 = up to 1.3 m, 2 = up to 3 m, 3 = up to 4 m
     16#00  write 1 to restore factory settings

   Writing the baud rate takes effect immediately, so the sensor answers - if at
   all - at the NEW rate and this end will not hear it. That is expected and is
   why OnTransactionDone does not retry. *)
IF NOT ConfigPending THEN
	ConfigStep.DeviceId		:= Step.DeviceId;
	ConfigStep.FunctionCode	:= 6;
	ConfigStep.Address		:= Register;
	ConfigStep.Quantity		:= 1;
	ConfigStep.Data[0]		:= Value;
	ConfigStep.AbortOnError	:= FALSE;
	ConfigPending			:= TRUE;
	RequestConfigWrite		:= TRUE;
ELSE
	RequestConfigWrite		:= FALSE;
END_IF

(* One decision per transaction, and one re-arm of the timer.

   The re-arm belongs here rather than in OnStepResult because a step skipped by
   an AbortOnError predecessor is never reported, and a sensor that has stopped
   answering must still be retried. OnTransactionDone always runs. *)
timerData.IN := TRUE;

(* A configuration write is finished either way. It is deliberately not retried:
   the write that changes the baud rate cannot be confirmed at the old baud rate,
   so a retry loop here would spin forever on a sensor that had in fact obeyed.
   It also says nothing about availability - a write that cannot be acknowledged
   is not evidence the sensor has gone away. *)
IF ConfigPending THEN
	ConfigPending := FALSE;
	RETURN;
END_IF

IF StepsRun = 0 THEN
	RETURN;
END_IF

(* Two independent verdicts on the same transaction, because they answer
   different questions. AvailFailures decides whether the sensor is reachable at
   all and needs hysteresis to be worth reading. The quality window records how
   well it is doing and deliberately has none - the whole point is to move while
   availability is still, so that a sensor which is degrading rather than
   disconnected is visible. *)
IF Failures >= StepsRun THEN
	IF AvailFailures < AvailabilityFailLimit THEN
		AvailFailures := AvailFailures + 1;
	END_IF
	QualityWindow[QualityIdx] := FALSE;
ELSE
	AvailFailures := 0;
	QualityWindow[QualityIdx] := TRUE;
END_IF

QualityIdx := (QualityIdx + 1) MOD (DINT_TO_INT(UPPER_BOUND(QualityWindow, 1)) + 1);
IF QualitySeen <= DINT_TO_INT(UPPER_BOUND(QualityWindow, 1)) THEN
	QualitySeen := QualitySeen + 1;
END_IF

(* Only over what has actually been observed, so the figure is honest from the
   first transaction rather than starting at a flattering 100 for sixteen. *)
qualityOk := 0;
FOR qualityI := 0 TO QualitySeen - 1 DO
	IF QualityWindow[qualityI] THEN
		qualityOk := qualityOk + 1;
	END_IF
END_FOR

IF QualitySeen > 0 THEN
	SuccessRate := INT_TO_USINT((qualityOk * 100) / QualitySeen);
	isQualityUpdated := TRUE;
END_IF

(* Published only when the verdict changes, and once at startup so a retained
   value exists before anything has gone wrong. Republishing 'online' every two
   seconds for the life of the PLC tells nobody anything and is most of the
   traffic this block would otherwise generate. *)
IF AvailFailures >= AvailabilityFailLimit THEN
	IF AvailOnline OR NOT AvailKnown THEN
		AvailOnline := FALSE;
		AvailKnown := TRUE;
		PubMqttMessage(Suffix := '/availability', Data := 'offline');
	END_IF
ELSIF AvailFailures = 0 THEN
	IF NOT AvailOnline OR NOT AvailKnown THEN
		AvailOnline := TRUE;
		AvailKnown := TRUE;
		PubMqttMessage(Suffix := '/availability', Data := 'online');
	END_IF
END_IF

(* A configuration write echoes the request back rather than returning data; the
   transport has already checked that echo, so there is nothing to decode here. *)
IF ConfigPending THEN
	RETURN;
END_IF

THIS^.Error := Failed;

(* Count is what actually came back, not what was asked for, so a short reply
   cannot be read past the end of. *)
IF NOT Failed AND Count >= 2 THEN
	THIS^.OUTPUT_STATE		:= WORD_TO_BYTE(pData^[1] AND 16#00FF);
	THIS^.MeasurementValid	:= (THIS^.OUTPUT_STATE = 0);
	THIS^.isStateUpdated	:= TRUE;

	(* Hold the last good distance rather than publishing one the sensor has
	   just told us not to trust. A stale reading is visibly stale next to a
	   state that is not 'valid'; a wrong one is not visible at all. *)
	IF THIS^.MeasurementValid THEN
		THIS^.DISTANCE		:= WORD_TO_UINT(pData^[0]);
		THIS^.DataAvailable	:= TRUE;
		THIS^.isDataUpdated	:= TRUE;
	END_IF
END_IF

(* A configuration write goes alone and goes first. It is not batched with the
   read because several of these registers change how the sensor talks - the
   baud rate register is the obvious one - and a read queued behind such a write
   would be sent into a sensor that has already stopped listening at this speed. *)
IF ConfigPending THEN
	pSteps^[0]			:= ConfigStep;
	BuildTransaction	:= 1;
ELSIF timerData.Q THEN
	timerData.IN		:= FALSE;
	pSteps^[0]			:= Step;
	BuildTransaction	:= 1;
ELSE
	BuildTransaction	:= 0;
END_IF

(* Predicate only - the scheduler calls this on every device every cycle, and
   twice when it is looking for commands first. Nothing here may change state. *)
IF ConfigPending THEN
	HasWork := RS485_WorkLevel.COMMAND;
ELSIF timerData.Q THEN
	HasWork := RS485_WorkLevel.POLL;
ELSE
	HasWork := RS485_WorkLevel.NONE;
END_IF

(* Announces the sensor as a device of its own, then one entity per thing it reports. Distance carries no StateClass: it is a position, not a quantity worth averaging or totalling, and Home Assistant's long-term statistics on it would be meaningless. *) IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId := overruleId);
Device^.initDFRobotDevice( name := DeviceName, id := id, Model := Model, availabilityTopic1 := MqttVariables.MqttAvailabilityTopic, availabilityTopic2 := CONCAT(THIS^.MQTTPublishTopic, '/availability'), availabilityOnline := MqttVariables.MqttAvailabilityOnlinePayload, availabilityOffline := MqttVariables.MqttAvailabilityOfflinePayload, MqttDiscoveryPrefix := MqttVariables.MqttHADiscoveryPrefix, MqttDiagnosticTopic := MqttVariables.MqttDiagnosticTopic, pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue));
Device^.CreateSensorEntity( Name := 'Distance', Id := CONCAT(id, '_DIST'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/DIST'), DeviceClass := 'distance', UnitOfMeasurement := 'mm');
(* Diagnostic rather than a headline reading: it is what you look at when the distance stops making sense, not something to put on a dashboard. *) Device^.CreateDiagnosticSensorEntity( Name := 'Measurement state', Id := CONCAT(id, '_STATE'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/STATE'));
(* Diagnostic, with a unit and a state class so Home Assistant will graph it and keep statistics. This is the entity to put an automation on: a sensor that starts answering nine polls in ten instead of ten shows up here while availability is still reporting a cheerful 'online'. *) Device^.CreateDiagnosticSensorEntity( Name := 'Link quality', Id := CONCAT(id, '_QUALITY'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/QUALITY'), StateClass := 'measurement', UnitOfMeasurement := '%');
initMqttDiscoveryDone := TRUE; END_IF

SUPER^._InstancePath := THIS^.InstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.MqttPublishTopicPrefix := MQTTPublishPrefix;
SUPER^.InitBaseMqtt();

(* Modbus address and poll rate describe the wiring, not a mode, so they are fixed for the life of the instance and belong here rather than in a runtime setter. Note the consequence: changing either afterwards means editing the declaration in the IDE - CODESYS stores an instance's FB_init arguments beside the declaration text, where no script can reach them.
16#34 is the measurement data register and 16#35 the output state; they are adjacent, so reading two registers gets both from one reply and they describe the same measurement rather than two moments a poll apart.
Function 3, not 4: this sensor exposes everything - readings and settings alike - as holding registers. *) THIS^.Step.DeviceId := DeviceAddress; THIS^.Step.FunctionCode := 3; THIS^.Step.Address := 16#34; THIS^.Step.Quantity := 2;
(* --- the poll rate is a hardware limit, not a preference -------------------- This sensor will not be read every two seconds. Measured on a PFC200 with the sensor alone on the bus, nothing else registered:
poll every 2 s ~19 requests per 30 s, ~4 answered - 25% success poll every 7 s ~4 requests per 30 s, ~4 answered - 100% poll every 10 s 3 requests per 30 s, 3 answered - 100%, zero failures
It answers roughly once every six or seven seconds however often it is asked, and the requests in between are simply dropped. Ask faster and the only thing that changes is the proportion that fail, which is what made the Home Assistant connectivity sensor flap: three consecutive misses is easy to reach at 2 s and impossible at 10 s.
So the interval is clamped rather than trusted. A caller asking for something this device cannot sustain gets a working sensor and a slower one, which is the better failure: the alternative is a reading that is right a quarter of the time and an entity that keeps going unavailable. *) IF DataPollingInterval < SEN0492_MIN_POLL THEN THIS^.timerData.PT := SEN0492_MIN_POLL; ELSE THIS^.timerData.PT := DataPollingInterval; END_IF THIS^.timerData.IN := TRUE;
FB_init := TRUE;

IF pRequest = 0 THEN
	GetCommissioning := FALSE;
	RETURN;
END_IF

(* Can this sensor even be told to use the bus rate? The code is the index of the
   rate in its own table, so a rate that is not in the table has no code, and the
   honest answer is then to withdraw: moving the sensor to a rate it can express
   but the bus does not use would leave it just as inaudible, at a setting nobody
   went looking for. *)
code := -1;
FOR i := 0 TO DINT_TO_INT(UPPER_BOUND(BAUD_RATES, 1)) DO
	IF BAUD_RATES[i] = BusBaudrate THEN
		code := i;
	END_IF
END_FOR

IF code < 0 THEN
	GetCommissioning := FALSE;
	RETURN;
END_IF

(* Where to probe, and what a reply means. Everything on this sensor - readings and
   settings alike - is a holding register, so it is function 3 to read and 6 to
   write. The probe is the same measurement read the block polls with, because the
   point is not the distance: it is that something answered at this setting. *)
pRequest^.DeviceId			:= Step.DeviceId;
pRequest^.ProbeFunction		:= 3;
pRequest^.ProbeAddress		:= Step.Address;
pRequest^.ProbeQuantity		:= Step.Quantity;
pRequest^.WriteFunction		:= 6;
pRequest^.WriteAddress		:= REG_BAUDRATE;
pRequest^.WriteValue		:= INT_TO_WORD(code);

(* The bus rate first, so a sensor that has already been moved costs one exchange
   and the sweep ends there - the normal case after the first successful boot. The
   factory rate second, because that is where a fresh or factory-reset sensor is.
   Then the rest, for a sensor somebody has left half-configured. *)
pRequest^.Bauds[0] := BusBaudrate;
n := 1;
IF FACTORY_BAUD <> BusBaudrate THEN
	pRequest^.Bauds[n] := FACTORY_BAUD;
	n := n + 1;
END_IF
FOR i := 0 TO DINT_TO_INT(UPPER_BOUND(BAUD_RATES, 1)) DO
	IF BAUD_RATES[i] <> BusBaudrate AND BAUD_RATES[i] <> FACTORY_BAUD THEN
		pRequest^.Bauds[n] := BAUD_RATES[i];
		n := n + 1;
	END_IF
END_FOR
pRequest^.BaudCount := n;

(* Framing as well as rate, because those are the two things that silence a device
   on a working pair. 255 leaves the port's own framing - the ordinary case, tried
   first - and 1..3 force the raw SysCom code, which is how two stop bits is
   reached without depending on an enumerator name this runtime may spell
   differently. The sensor's own forum traffic reports 8N2; this bench found one
   stop bit answering on the first probe, so the sweep keeps both. *)
pRequest^.StopBits[0]	:= 255;
pRequest^.StopBits[1]	:= 1;
pRequest^.StopBits[2]	:= 2;
pRequest^.StopBits[3]	:= 3;
pRequest^.StopCount		:= 4;

(* Where the outcome is published, retained, under the bus prefix. *)
pRequest^.ReportTopic := 'SEN0492_COMMISSION';

GetCommissioning := TRUE;

timerData();

FOR loopCounter := 2 TO 30 DO
	Nodes[loopCounter]();
END_FOR

THIS^.timerData.PT := DataPollingInterval;

THIS^.MasterStep.DeviceId		:= DeviceAddress;
THIS^.MasterStep.FunctionCode	:= 4;
THIS^.MasterStep.Address		:= 10;
THIS^.MasterStep.Quantity		:= 6;

(* Address and value are filled in by PublishReceived when a command arrives. *)
THIS^.WriteStep.DeviceId		:= DeviceAddress;
THIS^.WriteStep.FunctionCode	:= 6;
THIS^.WriteStep.Quantity		:= 1;

THIS^.timerData.IN := TRUE;

THIS^.InitRS485Done := TRUE;

SUPER^._InstancePath := THIS^.InstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.MqttPublishTopicPrefix := MQTTPublishPrefix;
THIS^.MqttSubscribeTopicPrefix := MQTTSubscribePrefix;
SUPER^.InitBaseMqtt();

// register the FB agains the collector so mqtt events can be received
pMqttCallbackCollector^.put(instance:= THIS^);


FOR loopCounter := 2 TO 30 DO
		Nodes[loopCounter].InitMqtt(
			MQTTPublishPrefix := MQTTPublishPrefix,
			MqttPublishTopicSuffix := THIS^.MqttPublishTopicSuffix,
			pMqttPublishQueue := pMqttPublishQueue
		);
END_FOR

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(InitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
//check if the packet is for this FB
ELSIF MQTTSubscribeTopic = LEFT(Data.TopicOut^, LEN(MQTTSubscribeTopic)) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	// process the data
	(* Parse by delimiter rather than by fixed width. The old code took the last
	   nine characters and then one character each for the node and the register,
	   so a command on '.../12/write/3' parsed as node 2 - a write silently aimed
	   at a different physical device. This block supports nodes 2..30. *)
	SubTopic := RIGHT(Data.TopicOut^, LEN(Data.TopicOut^) - LEN(MQTTSubscribeTopic));
	writePos := FIND(SubTopic, '/write/');

	IF writePos >= 3 THEN
		// SubTopic is '/<node>/write/<register>', so the node digits occupy
		// positions 2..writePos-1 and the register is everything past '/write/'.
		NodeNumber := MID(SubTopic, writePos - 2, 2);
		NodeRegister := RIGHT(SubTopic, LEN(SubTopic) - (writePos + 6));
	ELSE
		NodeNumber := '';
		NodeRegister := '';
	END_IF

	IF writePos >= 3 AND
		OSCAT_BASIC.IS_NUM(NodeNumber) AND
		OSCAT_BASIC.IS_NUM(NodeRegister) AND
		OSCAT_BASIC.IS_NUM(Data.PayloadString^) AND
		STRING_TO_UINT(NodeNumber) >= 2 AND
		STRING_TO_UINT(NodeNumber) < THIS^.NodePointer THEN
			WriteStep.Address := (STRING_TO_UINT(NodeNumber) * 10) + STRING_TO_UINT(NodeRegister);
			WriteStep.Data[0] := STRING_TO_WORD(Data.PayloadString^);
			WriteQuerySuffix := SubTopic;
			WriteQueryPayload := Data.PayloadString^;
			WriteQueryReady := TRUE;
	END_IF
END_IF

(* Nodes is ARRAY[2..30]. Without this bound the 30th call wrote past the end of
   it, and the unassigned return value left the caller unable to notice. *)
IF NodePointer <= 30 THEN
	THIS^.Nodes[NodePointer].InitNode(
		DeviceAddress := THIS^.MasterStep.DeviceId,
		NodeNumber := NodePointer - 1,
		DataPollingInterval := DataPollingInterval
	);

	NodePointer := NodePointer + 1;
	AddNode := TRUE;
ELSE
	AddNode := FALSE;
END_IF

n := 0;

IF WriteQueryReady THEN
	WriteQueryReady := FALSE;

	(* Write, then read the same register straight back, with the bus held
	   across both. What this block used to do was publish the payload it had
	   just sent, as though sending it were proof - so Home Assistant showed a
	   value the Ducobox might never have taken. AbortOnError on the write is
	   what stops the read-back running, and therefore stops anything being
	   published, when the write itself fails. *)
	pSteps^[n]				:= WriteStep;
	pSteps^[n].AbortOnError	:= TRUE;
	StepMap[n]				:= 2;
	n						:= n + 1;

	ReadBackStep.DeviceId		:= WriteStep.DeviceId;
	(* Function 3: the register was written as a holding register, so that is
	   where it reads back from. If a Ducobox turns out to mirror these into the
	   input register space instead, this is the one line that changes. *)
	ReadBackStep.FunctionCode	:= 3;
	ReadBackStep.Address		:= WriteStep.Address;
	ReadBackStep.Quantity		:= 1;

	pSteps^[n]	:= ReadBackStep;
	StepMap[n]	:= 3;
	n			:= n + 1;
END_IF

IF timerData.Q THEN
	timerData.IN	:= FALSE;
	pSteps^[n]		:= MasterStep;
	StepMap[n]		:= 1;
	n				:= n + 1;
END_IF

(* One node per transaction, taken in turn from NodeCursor. *)
FOR k := 0 TO 28 DO
	i := 2 + ((NodeCursor - 2 + k) MOD 29);
	IF i < UINT_TO_INT(NodePointer) THEN
		IF Nodes[i].RequestBusTime() THEN
			pSteps^[n]	:= Nodes[i].GetStep();
			StepMap[n]	:= 10 + i;
			n			:= n + 1;
			NodeCursor	:= 2 + ((i - 1) MOD 29);
			EXIT;
		END_IF
	END_IF
END_FOR

BuildTransaction := n;

(* Pure predicate. Nodes[].RequestBusTime is one too, so asking them here costs
   nothing and cannot disturb anything - which is the reason the node kept that
   method while the parent's own version was replaced. *)
IF NOT InitRS485Done THEN
	HasWork := RS485_WorkLevel.NONE;
	RETURN;
END_IF

IF WriteQueryReady THEN
	(* Somebody is waiting on this: it arrived over MQTT, from Home Assistant or
	   a person. Ahead of routine polling, but still round-robin against other
	   devices' commands. *)
	HasWork := RS485_WorkLevel.COMMAND;
	RETURN;
END_IF

IF timerData.Q THEN
	HasWork := RS485_WorkLevel.POLL;
	RETURN;
END_IF

HasWork := RS485_WorkLevel.NONE;
FOR k := 2 TO 30 DO
	IF k < UINT_TO_INT(NodePointer) THEN
		IF Nodes[k].RequestBusTime() THEN
			HasWork := RS485_WorkLevel.POLL;
			RETURN;
		END_IF
	END_IF
END_FOR

IF StepIndex < 0 OR StepIndex > DINT_TO_INT(UPPER_BOUND(StepMap, 1)) THEN
	RETURN;
END_IF

stepKind := StepMap[StepIndex];

IF stepKind = 1 THEN
	(* Master unit *)
	THIS^.Error := Failed;
	THIS^.timerData.IN := TRUE;
	IF NOT Failed AND Count >= 6 THEN
		PubMqttMessage(Suffix := '/1/read/0', Data := WORD_TO_STRING(pData^[0]));
		PubMqttMessage(Suffix := '/1/read/1', Data := WORD_TO_STRING(pData^[1]));
		PubMqttMessage(Suffix := '/1/read/2', Data := WORD_TO_STRING(pData^[2]));
		PubMqttMessage(Suffix := '/1/read/3', Data := WORD_TO_STRING(pData^[3]));
		PubMqttMessage(Suffix := '/1/read/4', Data := WORD_TO_STRING(pData^[4]));
		PubMqttMessage(Suffix := '/1/read/5', Data := WORD_TO_STRING(pData^[5]));
	END_IF

ELSIF stepKind = 2 THEN
	(* The write. Deliberately publishes nothing: the value is only news once
	   the device has been read back and agrees. *)
	THIS^.Error := Failed;

ELSIF stepKind = 3 THEN
	(* The read-back. This is the value the device actually holds, which is the
	   whole point of pairing the two. *)
	IF NOT Failed AND Count >= 1 THEN
		(* Suffix already begins with '/', so this leading one doubles it. Kept
		   as it was: the topic is what Home Assistant is already subscribed to,
		   and it cannot be re-checked without a Ducobox on the bench. *)
		PubMqttMessage(Suffix := CONCAT('/', WriteQuerySuffix), Data := WORD_TO_STRING(pData^[0]));
	END_IF

ELSIF stepKind >= 12 AND stepKind <= 40 THEN
	Nodes[stepKind - 10].OnStepResult(Failed := Failed, pData := pData, Count := Count);
END_IF

(* One announcement per transaction, at the point the bus is released. *)
IF StepsRun > 0 AND Failures >= StepsRun THEN
	PubMqttMessage(Suffix := '/availability', Data := 'offline');
ELSIF StepsRun > 0 THEN
	PubMqttMessage(Suffix := '/availability', Data := 'online');
END_IF

IF NOT NodeInitialized THEN	
	RequestBusTime := FALSE;
ELSIF timerData.Q THEN
	RequestBusTime := TRUE;
ELSE
	RequestBusTime := FALSE;	
END_IF

THIS^.Step.DeviceId		:= DeviceAddress;
THIS^.Step.FunctionCode	:= 4;
THIS^.Step.Address		:= (NodeNumber * 10) + 10;
THIS^.Step.Quantity		:= 6;

THIS^.timerData.PT := DataPollingInterval;
THIS^.NodeNumber := NodeNumber + 1;

THIS^.timerData.IN := TRUE;

THIS^.NodeInitialized := TRUE;

THIS^.MqttPublishTopicPrefix := MQTTPublishPrefix;
THIS^.MqttPublishTopicSuffix := MqttPublishTopicSuffix;
THIS^.pMqttPublishQueue := pMqttPublishQueue;

THIS^.InitMqttDone := TRUE;

THIS^.timerData.IN := TRUE;

IF NOT Failed AND Count >= 6 THEN
	PubMqttMessage(Suffix := '/read/0', Data := WORD_TO_STRING(pData^[0]));
	PubMqttMessage(Suffix := '/read/1', Data := WORD_TO_STRING(pData^[1]));
	PubMqttMessage(Suffix := '/read/2', Data := WORD_TO_STRING(pData^[2]));
	PubMqttMessage(Suffix := '/read/3', Data := WORD_TO_STRING(pData^[3]));
	PubMqttMessage(Suffix := '/read/4', Data := WORD_TO_STRING(pData^[4]));
	PubMqttMessage(Suffix := '/read/5', Data := WORD_TO_STRING(pData^[5]));
END_IF

(* Modbus address, meter model and poll rate all describe the wiring rather than
   a mode, so they are fixed for the life of the instance and belong here rather
   than in a runtime setter. Note the consequence: changing any of them
   afterwards means editing the declaration in the IDE - CODESYS stores an
   instance's FB_init arguments beside the declaration text, where no script can
   reach them.

   DeviceType decides which register is read, and it is also the model this block
   announces itself to Home Assistant as. Setting it here means both are settled
   before the first cycle, so the discovery config cannot be published against a
   model that has not been chosen yet. *)
THIS^.StepSmallMeter.DeviceId		:= DeviceAddress;
THIS^.StepSmallMeter.FunctionCode	:= 4;
THIS^.StepSmallMeter.Address		:= 12;	(* SDM120 / SDM220 active power *)
THIS^.StepSmallMeter.Quantity		:= 2;

THIS^.StepSDM630.DeviceId		:= DeviceAddress;
THIS^.StepSDM630.FunctionCode	:= 4;
THIS^.StepSDM630.Address		:= 52;	(* SDM630 total active power *)
THIS^.StepSDM630.Quantity		:= 2;

THIS^.DeviceType := DeviceType;

THIS^.timerData.PT := DataPollingInterval;
THIS^.timerData.IN := TRUE;

FB_init := TRUE;

SUPER^._InstancePath := THIS^.InstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.MqttPublishTopicPrefix := MQTTPublishPrefix;
SUPER^.InitBaseMqtt();

BuildTransaction := 0;

IF timerData.Q THEN
	timerData.IN := FALSE;

	IF DeviceType = RS485_EASTRON_SDM_Devices.SDM630 THEN
		pSteps^[0]			:= StepSDM630;
		BuildTransaction	:= 1;
	ELSIF DeviceType = RS485_EASTRON_SDM_Devices.SDM120
	   OR DeviceType = RS485_EASTRON_SDM_Devices.SDM220 THEN
		pSteps^[0]			:= StepSmallMeter;
		BuildTransaction	:= 1;
	END_IF
	(* An unset DeviceType returns 0: the scheduler releases the bus and moves
	   on rather than sending a frame nobody asked for. *)
END_IF

THIS^.Error := Failed;
THIS^.timerData.IN := TRUE;

IF NOT Failed AND Count >= 2 THEN
	THIS^.ACTIVEPOWER := SwapWordsToReal(pData^[0], pData^[1]);
	THIS^.DataAvailable := TRUE;
	THIS^.isDataUpdated := TRUE;
END_IF

(* One announcement per transaction, at the point the bus is released. *)
IF StepsRun > 0 AND Failures >= StepsRun THEN
	PubMqttMessage(Suffix := '/availability', Data := 'offline');
ELSIF StepsRun > 0 THEN
	PubMqttMessage(Suffix := '/availability', Data := 'online');
END_IF

(* Announces the meter as a device carrying one sensor: active power. Unlike the SDM220 and SDM630 blocks this one serves three meter models, so the model string is derived from DeviceType rather than fixed - InitRS485 must therefore have run before this does, which is what the self-wiring prologue waits for. Pass Model explicitly to overrule the derivation. *) IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
IF Model <> '' THEN resolvedModel := Model; ELSE CASE DeviceType OF RS485_EASTRON_SDM_Devices.SDM120: resolvedModel := 'SDM120'; RS485_EASTRON_SDM_Devices.SDM220: resolvedModel := 'SDM220'; RS485_EASTRON_SDM_Devices.SDM630: resolvedModel := 'SDM630'; ELSE resolvedModel := 'unknown'; END_CASE END_IF
id := SUPER^.ResolveEntityId(overruleId := overruleId);
Device^.initEastronDevice( name := DeviceName, id := id, Model := resolvedModel, availabilityTopic1 := MqttVariables.MqttAvailabilityTopic, availabilityTopic2 := CONCAT(THIS^.MQTTPublishTopic, '/availability'), availabilityOnline := MqttVariables.MqttAvailabilityOnlinePayload, availabilityOffline := MqttVariables.MqttAvailabilityOfflinePayload, MqttDiscoveryPrefix := MqttVariables.MqttHADiscoveryPrefix, MqttDiagnosticTopic := MqttVariables.MqttDiagnosticTopic, pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue));
Device^.CreateSensorEntity( Name := 'Active Power', Id := CONCAT(id, '_ACTP'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/ACTP'), DeviceClass := 'power', StateClass := 'measurement', UnitOfMeasurement := 'W');
initMqttDiscoveryDone := TRUE; END_IF

(* --- self-wiring prologue ----------------------------------------------------
   Makes the InitMqtt and InitMqttDiscovery calls optional. Set FriendlyName at
   the declaration site and this block wires itself from MqttVariables on its
   first cyclic call, then announces itself to Home Assistant.

   Deliberately in the body rather than in FB_init: it dereferences GVL members
   and reads the reflection instance path, and doing that during initialisation
   would rely on an ordering nothing enforces and the compiler cannot check.

   Dormant while FriendlyName is empty, so existing projects and existing call
   sites keep working untouched.

   A block wired this way MUST be called cyclically. An instance whose body never
   runs is unwired and absent from Home Assistant, and nothing warns about that. *)
IF FriendlyName <> '' THEN

	IF NOT InitMqttDone THEN
		THIS^.InitMqtt(
			MQTTPublishPrefix := ADR(MqttVariables.MqttPubRS485Prefix),
			pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue));
	END_IF

	IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
		THIS^.InitMqttDiscovery(
			Device := ADR(THIS^.MqttDiscoveryDevice),
			DeviceName := FriendlyName);
	END_IF

END_IF

timerData();

(* Published through PubMqttMessage rather than by building each topic inline.
   The inline form concatenated the prefix and suffix at every one of these
   fourteen call sites, which is the same string MQTTPublishTopic already holds -
   and the discovery configs advertise MQTTPublishTopic. Two ways of spelling one
   topic is how a state topic and its discovery config drift apart. *)
IF Update1 THEN
	Update1 := FALSE;
	DataAvailable1 := TRUE;

	PubMqttMessage(Suffix := '/VOLT', Data := REAL_TO_STRING(VOLTAGE));
	PubMqttMessage(Suffix := '/CURR', Data := REAL_TO_STRING(CURRENT));
	PubMqttMessage(Suffix := '/ACTP', Data := REAL_TO_STRING(ACTIVEPOWER));
	PubMqttMessage(Suffix := '/APPP', Data := REAL_TO_STRING(APPARENT_POWER));
	PubMqttMessage(Suffix := '/REAP', Data := REAL_TO_STRING(REACTIVE_POWER));
	PubMqttMessage(Suffix := '/POWF', Data := REAL_TO_STRING(POWER_FACTOR));
	PubMqttMessage(Suffix := '/PHAA', Data := REAL_TO_STRING(PHASE_ANGLE));
END_IF

IF Update2 THEN
	Update2 := FALSE;
	DataAvailable2 := TRUE;

	PubMqttMessage(Suffix := '/FREQ', Data := REAL_TO_STRING(FREQUENCY));
	PubMqttMessage(Suffix := '/IMAE', Data := REAL_TO_STRING(IMPORT_ACTIVE_ENERGY));
	PubMqttMessage(Suffix := '/EXAE', Data := REAL_TO_STRING(EXPORT_ACTIVE_ENERGY));
	PubMqttMessage(Suffix := '/IMRE', Data := REAL_TO_STRING(IMPORT_REACTIVE_ENERGY));
	PubMqttMessage(Suffix := '/EXRE', Data := REAL_TO_STRING(EXPORT_REACTIVE_ENERGY));
END_IF

IF Update3 THEN
	Update3 := FALSE;
	DataAvailable3 := TRUE;

	PubMqttMessage(Suffix := '/TOTAE', Data := REAL_TO_STRING(TOTAL_ACTIVE_ENERGY));
	PubMqttMessage(Suffix := '/TOTRE', Data := REAL_TO_STRING(TOTAL_REACTIVE_ENERGY));
END_IF

SUPER^._InstancePath := THIS^.InstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.MqttPublishTopicPrefix := MQTTPublishPrefix;
SUPER^.InitBaseMqtt();

(* The whole meter in one grant of the bus. Three register blocks used to mean
   winning the bus three separate times, with every other device's traffic in
   between; and while they were separately timed, which of the three were due
   varied from round to round. They now always go together.

   StepMap records which block each step came from, because OnStepResult is told
   the step index and nothing else. *)
IF timerData.Q THEN
	timerData.IN := FALSE;

	pSteps^[0] := Steps[0];		StepMap[0] := 1;
	pSteps^[1] := Steps[1];		StepMap[1] := 2;
	pSteps^[2] := Steps[2];		StepMap[2] := 3;

	BuildTransaction := 3;
ELSE
	BuildTransaction := 0;
END_IF

IF StepIndex < 0 OR StepIndex > DINT_TO_INT(UPPER_BOUND(StepMap, 1)) THEN
	RETURN;
END_IF

(* Count is what actually came back, not what was asked for, so a short reply
   cannot be read past the end of. The timer is not re-armed here - see
   OnTransactionDone. *)
CASE StepMap[StepIndex] OF

1:	THIS^.Error1 := Failed;
	IF NOT Failed AND Count >= 38 THEN
		THIS^.VOLTAGE			:= SwapWordsToReal(pData^[0], pData^[1]);
		THIS^.CURRENT			:= SwapWordsToReal(pData^[6], pData^[7]);
		THIS^.ACTIVEPOWER		:= SwapWordsToReal(pData^[12], pData^[13]);
		THIS^.APPARENT_POWER	:= SwapWordsToReal(pData^[18], pData^[19]);
		THIS^.REACTIVE_POWER	:= SwapWordsToReal(pData^[24], pData^[25]);
		THIS^.POWER_FACTOR		:= SwapWordsToReal(pData^[30], pData^[31]);
		THIS^.PHASE_ANGLE		:= SwapWordsToReal(pData^[36], pData^[37]);
		THIS^.Update1 := TRUE;
	END_IF

2:	THIS^.Error2 := Failed;
	IF NOT Failed AND Count >= 10 THEN
		THIS^.FREQUENCY					:= SwapWordsToReal(pData^[0], pData^[1]);
		THIS^.IMPORT_ACTIVE_ENERGY		:= SwapWordsToReal(pData^[2], pData^[3]);
		THIS^.EXPORT_ACTIVE_ENERGY		:= SwapWordsToReal(pData^[4], pData^[5]);
		THIS^.IMPORT_REACTIVE_ENERGY	:= SwapWordsToReal(pData^[6], pData^[7]);
		THIS^.EXPORT_REACTIVE_ENERGY	:= SwapWordsToReal(pData^[8], pData^[9]);
		THIS^.Update2 := TRUE;
	END_IF

3:	THIS^.Error3 := Failed;
	IF NOT Failed AND Count >= 4 THEN
		THIS^.TOTAL_ACTIVE_ENERGY	:= SwapWordsToReal(pData^[0], pData^[1]);
		THIS^.TOTAL_REACTIVE_ENERGY	:= SwapWordsToReal(pData^[2], pData^[3]);
		THIS^.Update3 := TRUE;
	END_IF

END_CASE

(* One announcement per transaction, and one re-arm of the timer.

   The re-arm belongs here rather than in OnStepResult because a step skipped by
   an AbortOnError predecessor is never reported, and a meter that has stopped
   answering must still be retried. OnTransactionDone always runs. *)
timerData.IN := TRUE;

IF StepsRun > 0 AND Failures >= StepsRun THEN
	PubMqttMessage(Suffix := '/availability', Data := 'offline');
ELSIF StepsRun > 0 THEN
	PubMqttMessage(Suffix := '/availability', Data := 'online');
END_IF

(* Announces the meter as a device of its own, then one sensor entity per measurement. StateClass is what puts the energy totals into the Home Assistant energy dashboard; the instantaneous values are 'measurement', and power factor and phase angle carry none because neither is meaningful to sum or average over time.
The three kvarh counters use DeviceClass 'reactive_energy', which Home Assistant gained in 2025.9. On an older Home Assistant an unrecognised device class makes it reject the whole discovery config, so those three entities would not appear at all - the symptom is a missing entity, not a wrong one. *) IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId := overruleId);
Device^.initEastronDevice( name := DeviceName, id := id, Model := Model, availabilityTopic1 := MqttVariables.MqttAvailabilityTopic, availabilityTopic2 := CONCAT(THIS^.MQTTPublishTopic, '/availability'), availabilityOnline := MqttVariables.MqttAvailabilityOnlinePayload, availabilityOffline := MqttVariables.MqttAvailabilityOfflinePayload, MqttDiscoveryPrefix := MqttVariables.MqttHADiscoveryPrefix, MqttDiagnosticTopic := MqttVariables.MqttDiagnosticTopic, pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue));
(* --- register block 1: the instantaneous electrical values ------------- *)
Device^.CreateSensorEntity( Name := 'Voltage', Id := CONCAT(id, '_VOLT'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/VOLT'), DeviceClass := 'voltage', StateClass := 'measurement', UnitOfMeasurement := 'V');
Device^.CreateSensorEntity( Name := 'Current', Id := CONCAT(id, '_CURR'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/CURR'), DeviceClass := 'current', StateClass := 'measurement', UnitOfMeasurement := 'A');
Device^.CreateSensorEntity( Name := 'Active Power', Id := CONCAT(id, '_ACTP'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/ACTP'), DeviceClass := 'power', StateClass := 'measurement', UnitOfMeasurement := 'W');
Device^.CreateSensorEntity( Name := 'Apparent Power', Id := CONCAT(id, '_APPP'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/APPP'), DeviceClass := 'apparent_power', StateClass := 'measurement', UnitOfMeasurement := 'VA');
Device^.CreateSensorEntity( Name := 'Reactive Power', Id := CONCAT(id, '_REAP'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/REAP'), DeviceClass := 'reactive_power', StateClass := 'measurement', UnitOfMeasurement := 'var');
Device^.CreateSensorEntity( Name := 'Power Factor', Id := CONCAT(id, '_POWF'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/POWF'), DeviceClass := 'power_factor', UnitOfMeasurement := '');
Device^.CreateSensorEntity( Name := 'Phase Angle', Id := CONCAT(id, '_PHAA'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/PHAA'), DeviceClass := '', UnitOfMeasurement := '°');
(* --- register block 2: frequency and the four energy counters ---------- *)
Device^.CreateSensorEntity( Name := 'Frequency', Id := CONCAT(id, '_FREQ'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/FREQ'), DeviceClass := 'frequency', StateClass := 'measurement', UnitOfMeasurement := 'Hz');
Device^.CreateSensorEntity( Name := 'Import Active Energy', Id := CONCAT(id, '_IMAE'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/IMAE'), DeviceClass := 'energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kWh');
Device^.CreateSensorEntity( Name := 'Export Active Energy', Id := CONCAT(id, '_EXAE'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/EXAE'), DeviceClass := 'energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kWh');
Device^.CreateSensorEntity( Name := 'Import Reactive Energy', Id := CONCAT(id, '_IMRE'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/IMRE'), DeviceClass := 'reactive_energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kvarh');
Device^.CreateSensorEntity( Name := 'Export Reactive Energy', Id := CONCAT(id, '_EXRE'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/EXRE'), DeviceClass := 'reactive_energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kvarh');
(* --- register block 3: the totals -------------------------------------- *)
Device^.CreateSensorEntity( Name := 'Total Active Energy', Id := CONCAT(id, '_TOTAE'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/TOTAE'), DeviceClass := 'energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kWh');
Device^.CreateSensorEntity( Name := 'Total Reactive Energy', Id := CONCAT(id, '_TOTRE'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/TOTRE'), DeviceClass := 'reactive_energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kvarh');
initMqttDiscoveryDone := TRUE; END_IF

(* Modbus address and poll rate describe the wiring, not a mode, so they are
   fixed for the life of the instance and belong here rather than in a runtime
   setter. Note the consequence: changing either afterwards means editing the
   declaration in the IDE - CODESYS stores an instance's FB_init arguments beside
   the declaration text, where no script can reach them.

   ONE interval covers the whole meter. The SDM220 will not return more than 40
   registers in a reply and its measurements are not in one contiguous run, so
   reading it takes three requests - but that is a property of the meter, not a
   decision a caller should be asked to make. All three go out together as a
   single transaction, so they cost one turn of the bus rather than three. *)
THIS^.Steps[0].DeviceId		:= DeviceAddress;
THIS^.Steps[0].FunctionCode	:= 4;
THIS^.Steps[0].Address		:= 0;	(* voltage through phase angle *)
THIS^.Steps[0].Quantity		:= 40;

THIS^.Steps[1].DeviceId		:= DeviceAddress;
THIS^.Steps[1].FunctionCode	:= 4;
THIS^.Steps[1].Address		:= 70;	(* frequency, import and export energy *)
THIS^.Steps[1].Quantity		:= 10;

THIS^.Steps[2].DeviceId		:= DeviceAddress;
THIS^.Steps[2].FunctionCode	:= 4;
THIS^.Steps[2].Address		:= 342;	(* totals *)
THIS^.Steps[2].Quantity		:= 4;

THIS^.timerData.PT := DataPollingInterval;
THIS^.timerData.IN := TRUE;

FB_init := TRUE;

(* --- self-wiring prologue ----------------------------------------------------
   Makes the InitMqtt and InitMqttDiscovery calls optional. Set FriendlyName at
   the declaration site and this block wires itself from MqttVariables on its
   first cyclic call, then announces itself to Home Assistant.

   Deliberately in the body rather than in FB_init: it dereferences GVL members
   and reads the reflection instance path, and doing that during initialisation
   would rely on an ordering nothing enforces and the compiler cannot check. The
   body is the same lifecycle phase the init actions used, so this is not merely
   safe, it is the phase that already works today.

   The wiring calls this block's own unmodified InitMqtt / InitMqttDiscovery
   methods, so anything published - topics and discovery JSON alike - is produced
   by exactly the code that produces it today. Only the trigger moved.

   Dormant while FriendlyName is empty, so existing projects and existing call
   sites keep working untouched.

   A block wired this way MUST be called cyclically. An instance whose body never
   runs is now unwired and absent from Home Assistant, where the init action used
   to wire it regardless. Nothing warns about that.  *)
IF FriendlyName <> '' THEN

	IF NOT InitMqttDone THEN
		THIS^.InitMqtt(
			MQTTPublishPrefix := ADR(MqttVariables.MqttPubRS485Prefix),
			pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue));
	END_IF

	IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
		THIS^.InitMqttDiscovery(
			Device := ADR(THIS^.MqttDiscoveryDevice),
			DeviceName := FriendlyName);
	END_IF

END_IF

timerData();

(* Publish on change of data rather than on a timer: ProcessDataArray sets the
   flag when a response arrives, so the publish rate follows DataPollingInterval
   and nothing is republished while the bus is quiet. PubMqttMessage is a no-op
   until InitMqtt has run, so this needs no further guard. *)
IF isDataUpdated THEN
	isDataUpdated := FALSE;

	PubMqttMessage(Suffix := '/L1_ACTP', Data := REAL_TO_STRING(L1_ACTIVEPOWER));
	PubMqttMessage(Suffix := '/L2_ACTP', Data := REAL_TO_STRING(L2_ACTIVEPOWER));
	PubMqttMessage(Suffix := '/L3_ACTP', Data := REAL_TO_STRING(L3_ACTIVEPOWER));
	PubMqttMessage(Suffix := '/L1_VA', Data := REAL_TO_STRING(L1_VA));
	PubMqttMessage(Suffix := '/L2_VA', Data := REAL_TO_STRING(L2_VA));
	PubMqttMessage(Suffix := '/L3_VA', Data := REAL_TO_STRING(L3_VA));
	PubMqttMessage(Suffix := '/L1_VAR', Data := REAL_TO_STRING(L1_VAR));
	PubMqttMessage(Suffix := '/L2_VAR', Data := REAL_TO_STRING(L2_VAR));
	PubMqttMessage(Suffix := '/L3_VAR', Data := REAL_TO_STRING(L3_VAR));
	PubMqttMessage(Suffix := '/L1_PF', Data := REAL_TO_STRING(L1_PF));
	PubMqttMessage(Suffix := '/L2_PF', Data := REAL_TO_STRING(L2_PF));
	PubMqttMessage(Suffix := '/L3_PF', Data := REAL_TO_STRING(L3_PF));
	PubMqttMessage(Suffix := '/L1_PHI', Data := REAL_TO_STRING(L1_PHI));
	PubMqttMessage(Suffix := '/L2_PHI', Data := REAL_TO_STRING(L2_PHI));
	PubMqttMessage(Suffix := '/L3_PHI', Data := REAL_TO_STRING(L3_PHI));
	PubMqttMessage(Suffix := '/AVG_V', Data := REAL_TO_STRING(AVG_LN_V));
	PubMqttMessage(Suffix := '/AVG_I', Data := REAL_TO_STRING(AVG_LINE_I));
	PubMqttMessage(Suffix := '/SUM_I', Data := REAL_TO_STRING(SUM_LINE_I));
	PubMqttMessage(Suffix := '/ACTP', Data := REAL_TO_STRING(ACTIVEPOWER));
	PubMqttMessage(Suffix := '/TOT_VA', Data := REAL_TO_STRING(TOTAL_VA));
	PubMqttMessage(Suffix := '/TOT_VAR', Data := REAL_TO_STRING(TOTAL_VAR));
	PubMqttMessage(Suffix := '/TOT_PF', Data := REAL_TO_STRING(TOTAL_PF));
	PubMqttMessage(Suffix := '/TOT_PHI', Data := REAL_TO_STRING(TOTAL_PHI));
	PubMqttMessage(Suffix := '/FREQ', Data := REAL_TO_STRING(FREQUENCY));
	PubMqttMessage(Suffix := '/IMPE', Data := REAL_TO_STRING(TOTAL_IMPORT_ENERGY));
	PubMqttMessage(Suffix := '/EXPE', Data := REAL_TO_STRING(TOTAL_EXPORT_ENERGY));
END_IF

IF timerData.Q THEN
	HasWork := RS485_WorkLevel.POLL;
ELSE
	HasWork := RS485_WorkLevel.NONE;
END_IF

THIS^.Error := Failed; THIS^.timerData.IN := TRUE;
IF NOT Failed AND Count >= 64 THEN (* Every value is a big-endian IEEE float across two consecutive words, so the word index is the register offset from 16#000C doubled. Gaps below are registers the SDM630 reserves. *) THIS^.L1_ACTIVEPOWER := SwapWordsToReal(pData^[0], pData^[1]); // 16#000C L1 Active Power THIS^.L2_ACTIVEPOWER := SwapWordsToReal(pData^[2], pData^[3]); // 16#000E L2 Active Power THIS^.L3_ACTIVEPOWER := SwapWordsToReal(pData^[4], pData^[5]); // 16#0010 L3 Active Power THIS^.L1_VA := SwapWordsToReal(pData^[6], pData^[7]); // 16#0012 L1 Apparent Power THIS^.L2_VA := SwapWordsToReal(pData^[8], pData^[9]); // 16#0014 L2 Apparent Power THIS^.L3_VA := SwapWordsToReal(pData^[10], pData^[11]); // 16#0016 L3 Apparent Power THIS^.L1_VAR := SwapWordsToReal(pData^[12], pData^[13]); // 16#0018 L1 Reactive Power THIS^.L2_VAR := SwapWordsToReal(pData^[14], pData^[15]); // 16#001A L2 Reactive Power THIS^.L3_VAR := SwapWordsToReal(pData^[16], pData^[17]); // 16#001C L3 Reactive Power THIS^.L1_PF := SwapWordsToReal(pData^[18], pData^[19]); // 16#001E L1 Power Factor THIS^.L2_PF := SwapWordsToReal(pData^[20], pData^[21]); // 16#0020 L2 Power Factor THIS^.L3_PF := SwapWordsToReal(pData^[22], pData^[23]); // 16#0022 L3 Power Factor THIS^.L1_PHI := SwapWordsToReal(pData^[24], pData^[25]); // 16#0024 L1 Phase Angle THIS^.L2_PHI := SwapWordsToReal(pData^[26], pData^[27]); // 16#0026 L2 Phase Angle THIS^.L3_PHI := SwapWordsToReal(pData^[28], pData^[29]); // 16#0028 L3 Phase Angle THIS^.AVG_LN_V := SwapWordsToReal(pData^[30], pData^[31]); // 16#002A Average L-N Voltage THIS^.AVG_LINE_I := SwapWordsToReal(pData^[32], pData^[33]); // 16#002C Average Line Current THIS^.SUM_LINE_I := SwapWordsToReal(pData^[34], pData^[35]); // 16#002E Sum of Line Currents THIS^.ACTIVEPOWER := SwapWordsToReal(pData^[40], pData^[41]); // 16#0034 Active Power THIS^.TOTAL_VA := SwapWordsToReal(pData^[44], pData^[45]); // 16#0038 Total Apparent Power THIS^.TOTAL_VAR := SwapWordsToReal(pData^[48], pData^[49]); // 16#003C Total Reactive Power THIS^.TOTAL_PF := SwapWordsToReal(pData^[50], pData^[51]); // 16#003E Total Power Factor THIS^.TOTAL_PHI := SwapWordsToReal(pData^[54], pData^[55]); // 16#0042 Total Phase Angle THIS^.FREQUENCY := SwapWordsToReal(pData^[58], pData^[59]); // 16#0046 Frequency THIS^.TOTAL_IMPORT_ENERGY := SwapWordsToReal(pData^[60], pData^[61]); // 16#0048 Total Import Energy THIS^.TOTAL_EXPORT_ENERGY := SwapWordsToReal(pData^[62], pData^[63]); // 16#004A Total Export Energy
THIS^.DataAvailable := TRUE; THIS^.isDataUpdated := TRUE; END_IF

IF timerData.Q THEN
	pSteps^[0]			:= Step;
	timerData.IN		:= FALSE;
	BuildTransaction	:= 1;
ELSE
	BuildTransaction := 0;
END_IF

(* Announces the meter as a device of its own, then one sensor entity per measurement. StateClass is what puts the two kWh totals into the Home Assistant energy dashboard; the instantaneous values are 'measurement' and power factor, phase angle, voltage, current and frequency carry none. *) IF InitMqttDone AND NOT initMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId := overruleId);
Device^.initEastronDevice( name := DeviceName, id := id, Model := Model, availabilityTopic1 := MqttVariables.MqttAvailabilityTopic, availabilityTopic2 := CONCAT(THIS^.MQTTPublishTopic, '/availability'), availabilityOnline := MqttVariables.MqttAvailabilityOnlinePayload, availabilityOffline := MqttVariables.MqttAvailabilityOfflinePayload, MqttDiscoveryPrefix := MqttVariables.MqttHADiscoveryPrefix, MqttDiagnosticTopic := MqttVariables.MqttDiagnosticTopic, pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue));
Device^.CreateSensorEntity( Name := 'L1 Active Power', Id := CONCAT(id, '_L1_ACTP'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L1_ACTP'), DeviceClass := 'power', StateClass := 'measurement', UnitOfMeasurement := 'W');
Device^.CreateSensorEntity( Name := 'L2 Active Power', Id := CONCAT(id, '_L2_ACTP'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L2_ACTP'), DeviceClass := 'power', StateClass := 'measurement', UnitOfMeasurement := 'W');
Device^.CreateSensorEntity( Name := 'L3 Active Power', Id := CONCAT(id, '_L3_ACTP'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L3_ACTP'), DeviceClass := 'power', StateClass := 'measurement', UnitOfMeasurement := 'W');
Device^.CreateSensorEntity( Name := 'L1 Apparent Power', Id := CONCAT(id, '_L1_VA'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L1_VA'), DeviceClass := 'apparent_power', StateClass := 'measurement', UnitOfMeasurement := 'VA');
Device^.CreateSensorEntity( Name := 'L2 Apparent Power', Id := CONCAT(id, '_L2_VA'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L2_VA'), DeviceClass := 'apparent_power', StateClass := 'measurement', UnitOfMeasurement := 'VA');
Device^.CreateSensorEntity( Name := 'L3 Apparent Power', Id := CONCAT(id, '_L3_VA'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L3_VA'), DeviceClass := 'apparent_power', StateClass := 'measurement', UnitOfMeasurement := 'VA');
Device^.CreateSensorEntity( Name := 'L1 Reactive Power', Id := CONCAT(id, '_L1_VAR'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L1_VAR'), DeviceClass := 'reactive_power', StateClass := 'measurement', UnitOfMeasurement := 'var');
Device^.CreateSensorEntity( Name := 'L2 Reactive Power', Id := CONCAT(id, '_L2_VAR'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L2_VAR'), DeviceClass := 'reactive_power', StateClass := 'measurement', UnitOfMeasurement := 'var');
Device^.CreateSensorEntity( Name := 'L3 Reactive Power', Id := CONCAT(id, '_L3_VAR'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L3_VAR'), DeviceClass := 'reactive_power', StateClass := 'measurement', UnitOfMeasurement := 'var');
Device^.CreateSensorEntity( Name := 'L1 Power Factor', Id := CONCAT(id, '_L1_PF'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L1_PF'), DeviceClass := 'power_factor', UnitOfMeasurement := '');
Device^.CreateSensorEntity( Name := 'L2 Power Factor', Id := CONCAT(id, '_L2_PF'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L2_PF'), DeviceClass := 'power_factor', UnitOfMeasurement := '');
Device^.CreateSensorEntity( Name := 'L3 Power Factor', Id := CONCAT(id, '_L3_PF'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L3_PF'), DeviceClass := 'power_factor', UnitOfMeasurement := '');
Device^.CreateSensorEntity( Name := 'L1 Phase Angle', Id := CONCAT(id, '_L1_PHI'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L1_PHI'), DeviceClass := '', UnitOfMeasurement := '°');
Device^.CreateSensorEntity( Name := 'L2 Phase Angle', Id := CONCAT(id, '_L2_PHI'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L2_PHI'), DeviceClass := '', UnitOfMeasurement := '°');
Device^.CreateSensorEntity( Name := 'L3 Phase Angle', Id := CONCAT(id, '_L3_PHI'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/L3_PHI'), DeviceClass := '', UnitOfMeasurement := '°');
Device^.CreateSensorEntity( Name := 'Average L-N Voltage', Id := CONCAT(id, '_AVG_V'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/AVG_V'), DeviceClass := 'voltage', UnitOfMeasurement := 'V');
Device^.CreateSensorEntity( Name := 'Average Line Current', Id := CONCAT(id, '_AVG_I'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/AVG_I'), DeviceClass := 'current', UnitOfMeasurement := 'A');
Device^.CreateSensorEntity( Name := 'Sum of Line Currents', Id := CONCAT(id, '_SUM_I'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/SUM_I'), DeviceClass := 'current', UnitOfMeasurement := 'A');
Device^.CreateSensorEntity( Name := 'Active Power', Id := CONCAT(id, '_ACTP'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/ACTP'), DeviceClass := 'power', StateClass := 'measurement', UnitOfMeasurement := 'W');
Device^.CreateSensorEntity( Name := 'Total Apparent Power', Id := CONCAT(id, '_TOT_VA'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/TOT_VA'), DeviceClass := 'apparent_power', StateClass := 'measurement', UnitOfMeasurement := 'VA');
Device^.CreateSensorEntity( Name := 'Total Reactive Power', Id := CONCAT(id, '_TOT_VAR'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/TOT_VAR'), DeviceClass := 'reactive_power', StateClass := 'measurement', UnitOfMeasurement := 'var');
Device^.CreateSensorEntity( Name := 'Total Power Factor', Id := CONCAT(id, '_TOT_PF'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/TOT_PF'), DeviceClass := 'power_factor', UnitOfMeasurement := '');
Device^.CreateSensorEntity( Name := 'Total Phase Angle', Id := CONCAT(id, '_TOT_PHI'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/TOT_PHI'), DeviceClass := '', UnitOfMeasurement := '°');
Device^.CreateSensorEntity( Name := 'Frequency', Id := CONCAT(id, '_FREQ'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/FREQ'), DeviceClass := 'frequency', UnitOfMeasurement := 'Hz');
Device^.CreateSensorEntity( Name := 'Total Import Energy', Id := CONCAT(id, '_IMP_ENERG'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/IMPE'), DeviceClass := 'energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kWh');
Device^.CreateSensorEntity( Name := 'Total Export Energy', Id := CONCAT(id, '_EXP_ENERG'), StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/EXPE'), DeviceClass := 'energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kWh');
initMqttDiscoveryDone := TRUE; END_IF

SUPER^._InstancePath := THIS^.InstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.MqttPublishTopicPrefix := MQTTPublishPrefix;

SUPER^.InitBaseMqtt();

(* Modbus address and poll rate describe the wiring, not a mode, so they are
   fixed for the life of the instance and belong here rather than in a runtime
   setter. Note the consequence: changing either afterwards means editing the
   declaration in the IDE - CODESYS stores an instance's FB_init arguments beside
   the declaration text, where no script can reach them. *)
THIS^.Step.DeviceId		:= DeviceAddress;
THIS^.Step.FunctionCode	:= 4;
THIS^.Step.Address		:= 12;	(* 16#000C, phase 1 active power *)
THIS^.Step.Quantity		:= 64;	(* through 16#004B, total export energy *)

THIS^.timerData.PT := DataPollingInterval;
THIS^.timerData.IN := TRUE;

FB_init := TRUE;

(* One announcement per transaction, at the point the bus is released. *)
IF StepsRun > 0 AND Failures >= StepsRun THEN
	PubMqttMessage(Suffix := '/availability', Data := 'offline');
ELSIF StepsRun > 0 THEN
	PubMqttMessage(Suffix := '/availability', Data := 'online');
END_IF

IF timerData.Q THEN
	HasWork := RS485_WorkLevel.POLL;
ELSE
	HasWork := RS485_WorkLevel.NONE;
END_IF

THIS^.timerData.IN := TRUE;

(* Register 12 is the gateway's own status word for this sensor: non-zero means
   the gateway answered but the 1-Wire device behind it did not. A short reply
   is treated the same way - there is no status to trust. *)
IF Failed OR Count < 17 OR WORD_TO_INT(pData^[12]) <> 0 THEN
	THIS^.Error := TRUE;
	(* A single miss is normal on a 1-Wire bus, so availability only drops after
	   AllowedErrorCount of them in a row. *)
	IF THIS^.CurrentErrorCount >= THIS^.AllowedErrorCount THEN
		PubMqttMessage(Suffix := '/availability', Data := 'offline');
	END_IF
	THIS^.CurrentErrorCount := THIS^.CurrentErrorCount + 1;
	RETURN;
END_IF

THIS^.Error := FALSE;
THIS^.DataAvailable := TRUE;
THIS^.CurrentErrorCount := 0;
PubMqttMessage(Suffix := '/availability', Data := 'online');

IF initMqttDiscoveryDone THEN
	THIS^.MqttDiscoveryDevice^.SendDeviceUpdate(Model := WORD_TO_STRING(pData^[16]));
END_IF

// Data handling
IF pData^[16] = 11151 OR pData^[16] = 11152 THEN // Temperature, humidity & air quality
	ProcessTemperature(pData^[0]);
	ProcessOwdVoltage(pData^[2]);
	ProcessHumidity(pData^[4]);
	ProcessDewPoint(pData^[6]);
	ProcessAirQuality(pData^[8]);
ELSIF pData^[16] = 11102 OR pData^[16] = 11113 OR pData^[16] = 11120 OR pData^[16] = 11148 OR pData^[16] = 11150 OR pData^[16] = 11160 THEN // Temperature, humidity
	ProcessTemperature(pData^[0]);
	ProcessOwdVoltage(pData^[2]);
	ProcessHumidity(pData^[4]);
	ProcessDewPoint(pData^[6]);
ELSIF pData^[16] = 11121 OR pData^[16] = 11132 OR pData^[16] = 11134 OR pData^[16] = 11135 THEN // Temperature, humidity, brightness
	ProcessTemperature(pData^[0]);
	ProcessOwdVoltage(pData^[2]);
	ProcessHumidity(pData^[4]);
	ProcessDewPoint(pData^[6]);
	ProcessBrigthness(pData^[8]);
ELSIF pData^[16] = 1820 THEN // Temperature DS18B20
	ProcessTemperature(pData^[0]);
END_IF

IF timerData.Q THEN
	pSteps^[0]			:= Step;
	timerData.IN		:= FALSE;
	BuildTransaction	:= 1;
ELSE
	BuildTransaction := 0;
END_IF

IF InitMqttDone AND NOT initMqttDiscoveryDone THEN

	THIS^.MqttDiscoveryDevice := Device;

	id := SUPER^.ResolveEntityId(overruleId := '');

	Device^.init1WireDevice(
		name := DeviceName,
		id := id);

	IF SupportsTemperature THEN
		Device^.CreateSensorEntity(
			Name := 'Temperature',
			Id := CONCAT(id, '_TEMP'),
			StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/TEMP'),
			DeviceClass := 'temperature',
			UnitOfMeasurement := '°C'); 
	END_IF;	

	IF SupportsHumidity THEN
		Device^.CreateSensorEntity(
			Name := 'Humidity',
			Id := CONCAT(id, '_HUM'),
			StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/HUM'),
			DeviceClass := 'humidity',
			UnitOfMeasurement := '%');
	END_IF;

	IF SupportsCO2 THEN
		Device^.CreateSensorEntity(
			Name := 'Carbon Dioxide',
			Id := CONCAT(id, '_CO2'),
			StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/CO2'),
			DeviceClass := 'carbon_dioxide',
			UnitOfMeasurement := 'ppm');
	END_IF;

	IF SupportsDewPoint THEN
		Device^.CreateSensorEntity(
			Name := 'Dew Point',
			Id := CONCAT(id, '_DEWP'),
			StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/DEWP'),
			DeviceClass := 'temperature',
			UnitOfMeasurement := '°C'); 
	END_IF;	

	IF SupportsBrightness THEN
		Device^.CreateSensorEntity(
			Name := 'Brightness',
			Id := CONCAT(id, '_ILLUM'),
			StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/ILLUM'),
			DeviceClass := 'illuminance');
	END_IF;	

	IF SupportsOwdVoltage THEN
		Device^.CreateDiagnosticSensorEntity(
			Name := 'Operating Voltage',
			Id := CONCAT(id, '_OWDV'),
			StateTopic := CONCAT(THIS^.MQTTPublishTopic, '/OWDV'));
	END_IF;

	initMqttDiscoveryDone := TRUE;
END_IF

SUPER^._InstancePath := THIS^.InstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.MqttPublishTopicPrefix:=MQTTPublishPrefix;
SUPER^.InitBaseMqtt();

THIS^.BRIGHTNESS := WORD_TO_REAL(Data) / 100;
(* /ILLUM, matching the entity id and the StateTopic in InitMqttDiscovery.
   This published to /BNESS, so the illuminance entity never received a value. *)
PubMqttMessage(Suffix := '/ILLUM', Data := REAL_TO_STRING(BRIGHTNESS));

THIS^.Step.DeviceId		:= DeviceAddress;
THIS^.Step.FunctionCode	:= 3;
THIS^.Step.Address		:= OwdNumber * 100;
THIS^.Step.Quantity		:= 17;

THIS^.timerData.PT := DataPollingInterval;
THIS^.OwdNumber := OwdNumber;

THIS^.timerData.IN := TRUE;

FB_Init := TRUE;

(* ---------------------------------------------------------------- the port *)
IF ReopenRequest THEN
	ReopenRequest := FALSE;
	IF PortOpen THEN
		SysCom.SysComClose(hPort);
	END_IF
	PortOpen	:= FALSE;
	PortError	:= FALSE;
	State		:= 0;
	Outcome		:= RS485_StepState.IDLE;
END_IF

IF Configured AND NOT PortOpen AND NOT PortError THEN
	hPort		:= SysCom.SysComOpen2(pSettings := ADR(Settings), pSettingsEx := 0, pResult := ADR(rtsResult));
	PortError	:= (hPort = RTS_INVALID_HANDLE OR rtsResult <> 0);
	PortOpen	:= NOT PortError;
END_IF

(* Both timers are called unconditionally. A TON left with IN true while the
   state machine is elsewhere goes on counting, and would then fire instantly
   on the next step. *)
gap(IN := (State = 1) AND NOT restartGap, PT := GapTime);
replyTimer(IN := (State = 1) AND NOT restartReply, PT := ReplyTimeout);
restartGap		:= FALSE;
restartReply	:= FALSE;

(* ------------------------------------------------------- the step in flight *)
CASE State OF

0:	(* Idle. OK and FAILED were each returned for exactly one cycle, by the
	   return at the bottom of the cycle that reached state 2. *)
	Outcome := RS485_StepState.IDLE;

1:	(* Collect until the line has been quiet for GapTime, which is how RTU
	   delimits a frame, or until the slave has clearly not answered at all. *)
	IF RxCount < SIZEOF(Rx) THEN
		pRx := ADR(Rx);
		pRx := pRx + RxCount;
		n := SysCom.SysComRead(hPort, pRx, SIZEOF(Rx) - RxCount, 0, ADR(rtsResult));
		IF n > 0 THEN
			RxCount		:= RxCount + n;
			restartGap	:= TRUE;
		END_IF
	END_IF

	(* A frame whose CRC already checks out is complete by definition, so there
	   is nothing left to wait for. Waiting anyway costs about three task cycles
	   per step, and on a 200 ms task that is most of what a Modbus exchange
	   takes: measured at 1.87 s per step before this check, against roughly
	   100 ms of actual wire time at 9600 baud.

	   The silence timer stays as the fallback for everything that does not
	   frame cleanly - a partial reply, a burst of noise, a slave that answers
	   with something we cannot parse. *)
	count := UDINT_TO_INT(RxCount);
	IF count >= 5 AND THIS^.Frame() THEN
		State := 2;
	ELSIF (RxCount > 0 AND gap.Q) OR replyTimer.Q OR RxCount >= SIZEOF(Rx) THEN
		State := 2;
	END_IF

2:	THIS^.Judge();
	State := 0;

END_CASE

Service := Outcome;

Start := FALSE;

IF pStep = 0 OR NOT PortOpen OR State <> 0 THEN
	RETURN;
END_IF

(* Private copy. The scheduler's step list is scratch that it reuses for the
   next device, so nothing may be read back out of it later - the echo checks
   below run against this copy. *)
Step := pStep^;
qty := UINT_TO_INT(Step.Quantity);

CASE Step.FunctionCode OF

3, 4:	(* read holding / read input registers *)
	IF qty < 1 OR qty > (DINT_TO_INT(UPPER_BOUND(Data, 1)) + 1) THEN
		RETURN;
	END_IF
	Tx[0] := Step.DeviceId;
	Tx[1] := Step.FunctionCode;
	Tx[2] := UINT_TO_BYTE(SHR(Step.Address, 8));
	Tx[3] := UINT_TO_BYTE(Step.Address AND 16#00FF);
	Tx[4] := UINT_TO_BYTE(SHR(Step.Quantity, 8));
	Tx[5] := UINT_TO_BYTE(Step.Quantity AND 16#00FF);
	TxLen := 6;

6:	(* write single register: the value goes where the quantity would *)
	Tx[0] := Step.DeviceId;
	Tx[1] := 16#06;
	Tx[2] := UINT_TO_BYTE(SHR(Step.Address, 8));
	Tx[3] := UINT_TO_BYTE(Step.Address AND 16#00FF);
	Tx[4] := WORD_TO_BYTE(SHR(Step.Data[0], 8));
	Tx[5] := WORD_TO_BYTE(Step.Data[0] AND 16#00FF);
	TxLen := 6;

16:	(* write multiple registers: header, byte count, then the payload *)
	IF qty < 1 OR qty > (DINT_TO_INT(UPPER_BOUND(Step.Data, 1)) + 1) THEN
		RETURN;
	END_IF
	Tx[0] := Step.DeviceId;
	Tx[1] := 16#10;
	Tx[2] := UINT_TO_BYTE(SHR(Step.Address, 8));
	Tx[3] := UINT_TO_BYTE(Step.Address AND 16#00FF);
	Tx[4] := UINT_TO_BYTE(SHR(Step.Quantity, 8));
	Tx[5] := UINT_TO_BYTE(Step.Quantity AND 16#00FF);
	Tx[6] := INT_TO_BYTE(qty * 2);
	FOR i := 0 TO qty - 1 DO
		Tx[7 + 2 * i] := WORD_TO_BYTE(SHR(Step.Data[i], 8));
		Tx[8 + 2 * i] := WORD_TO_BYTE(Step.Data[i] AND 16#00FF);
	END_FOR
	TxLen := 7 + 2 * qty;

ELSE
	(* Refused, not guessed at. Guessing is precisely the bug this replaces:
	   every function code used to be framed from the read fields, so an FC6
	   write went out as "write register 0 := 0" and its echoed reply was then
	   parsed as though byte 2 were a length. *)
	RETURN;

END_CASE

(* Anything still in the receive buffer belongs to the previous exchange and
   would otherwise be collected as this one's reply. *)
n := SysCom.SysComRead(hPort, ADR(Flush), SIZEOF(Flush), 0, ADR(rtsResult));

crc := THIS^.Crc16(pBuf := ADR(Tx), Len := TxLen);
Tx[TxLen]		:= WORD_TO_BYTE(crc AND 16#00FF);
Tx[TxLen + 1]	:= WORD_TO_BYTE(SHR(crc, 8));

SysCom.SysComWrite(hPort, ADR(Tx), INT_TO_UDINT(TxLen + 2), 100, ADR(rtsResult));

RxCount			:= 0;
RegCount		:= 0;
restartGap		:= TRUE;
restartReply	:= TRUE;
Outcome			:= RS485_StepState.BUSY;
State			:= 1;
Start			:= TRUE;

count		:= UDINT_TO_INT(RxCount);
gotFrame	:= THIS^.Frame();

(* Leading glitch bytes are the slave's driver enabling onto an undriven pair,
   trailing ones its releasing. Both are normal on this hardware. *)
IF first > 0 THEN
	LeadNulls := LeadNulls + 1;
END_IF
IF gotFrame AND last < count THEN
	TrailNulls := TrailNulls + 1;
END_IF

frameLen	:= last - first;
RegCount	:= 0;
valid		:= FALSE;

IF count = 0 OR (count - first) = 0 THEN
	NoReply := NoReply + 1;

ELSIF (count - first) < 5 THEN
	ShortFrame := ShortFrame + 1;

ELSIF NOT gotFrame THEN
	CrcFail := CrcFail + 1;

	(* Capture what actually arrived. Two theories about these failures have now
	   been wrong - leading glitch bytes, then a framer that could not
	   resynchronise - and both were argued from counters rather than from
	   bytes. A counter says a frame did not check out; it cannot say whether
	   what arrived was half a reply, two replies, an echo, or noise. Decimal
	   rather than hex because there is no hex helper in scope and the point is
	   to read it off an MQTT topic, not to look pretty. *)
	LastFailLen := RxCount;

	(* Whose window this landed in. Without it the bytes are unattributable, and
	   a frame that looks like somebody else's request is exactly the case that
	   needs telling apart from a mangled reply. *)
	LastFailAddr := Step.DeviceId;
	LastFailFunc := Step.FunctionCode;

	LastFailBytes := '';
	FOR i := 0 TO count - 1 DO
		IF i >= 24 THEN
			EXIT;
		END_IF
		LastFailBytes := CONCAT(LastFailBytes, BYTE_TO_STRING(Rx[i]));
		LastFailBytes := CONCAT(LastFailBytes, ' ');
	END_FOR
	FOR i := 0 TO count - 1 DO
		IF i >= 24 THEN
			EXIT;
		END_IF
		LastFailBytes := CONCAT(LastFailBytes, BYTE_TO_STRING(Rx[i]));
		LastFailBytes := CONCAT(LastFailBytes, ' ');
	END_FOR

ELSIF Rx[first] <> Step.DeviceId THEN
	(* Well formed, intact, and not ours. On a shared bus that is somebody
	   else's traffic; on this one it means the reply was mis-framed. *)
	BadAddress := BadAddress + 1;

ELSIF Rx[first + 1] = (Step.FunctionCode OR 16#80) THEN
	Exceptions		:= Exceptions + 1;
	LastException	:= Rx[first + 2];

ELSIF Rx[first + 1] <> Step.FunctionCode THEN
	BadFunction := BadFunction + 1;

ELSE
	CASE Step.FunctionCode OF

	3, 4:	(* addr, fc, byte count, data, crc16 *)
		bytecount := BYTE_TO_INT(Rx[first + 2]);
		IF bytecount < 2 OR bytecount > (frameLen - 5) THEN
			ShortFrame := ShortFrame + 1;
		ELSE
			RegCount := bytecount / 2;
			IF RegCount > (DINT_TO_INT(UPPER_BOUND(Data, 1)) + 1) THEN
				RegCount := DINT_TO_INT(UPPER_BOUND(Data, 1)) + 1;
			END_IF
			(* Registers are big-endian on the wire, which is the order
			   SwapWordsToReal expects at the far end. *)
			FOR i := 0 TO RegCount - 1 DO
				Data[i] := SHL(BYTE_TO_WORD(Rx[first + 3 + 2 * i]), 8)
				           OR BYTE_TO_WORD(Rx[first + 4 + 2 * i]);
			END_FOR
			Ok		:= Ok + 1;
			valid	:= TRUE;
		END_IF

	6:	(* The reply is the request echoed back. There is no byte count in it,
		   and reading byte 2 as one - which is what this code did for every
		   function code before - reads an address high byte as a length. *)
		IF frameLen < 8 THEN
			ShortFrame := ShortFrame + 1;
		ELSE
			echoAddr	:= SHL(BYTE_TO_UINT(Rx[first + 2]), 8) OR BYTE_TO_UINT(Rx[first + 3]);
			echoValue	:= SHL(BYTE_TO_UINT(Rx[first + 4]), 8) OR BYTE_TO_UINT(Rx[first + 5]);
			IF echoAddr <> Step.Address OR echoValue <> WORD_TO_UINT(Step.Data[0]) THEN
				(* The slave acknowledged something other than what was asked.
				   Never report this as success: a read-after-write would then
				   publish a confirmation for a write that did not happen. *)
				BadEcho := BadEcho + 1;
			ELSE
				Ok		:= Ok + 1;
				valid	:= TRUE;
			END_IF
		END_IF

	16:	(* addr, 16, start address, quantity written, crc16 *)
		IF frameLen < 8 THEN
			ShortFrame := ShortFrame + 1;
		ELSE
			echoAddr	:= SHL(BYTE_TO_UINT(Rx[first + 2]), 8) OR BYTE_TO_UINT(Rx[first + 3]);
			echoValue	:= SHL(BYTE_TO_UINT(Rx[first + 4]), 8) OR BYTE_TO_UINT(Rx[first + 5]);
			IF echoAddr <> Step.Address OR echoValue <> Step.Quantity THEN
				BadEcho := BadEcho + 1;
			ELSE
				Ok		:= Ok + 1;
				valid	:= TRUE;
			END_IF
		END_IF

	END_CASE
END_IF

IF valid THEN
	Outcome := RS485_StepState.OK;
ELSE
	Outcome := RS485_StepState.FAILED;
END_IF

(* Modbus RTU CRC16: polynomial 16#A001, seed 16#FFFF, transmitted low byte
   first. A whole valid frame including its own CRC therefore checksums to zero,
   which is how a received frame is judged - no need to know where the data
   ends before deciding whether it is intact. *)
acc := 16#FFFF;
p := pBuf;

FOR i := 0 TO Len - 1 DO
	acc := acc XOR BYTE_TO_WORD(p[i]);
	FOR b := 0 TO 7 DO
		IF (acc AND 16#0001) <> 0 THEN
			acc := SHR(acc, 1) XOR 16#A001;
		ELSE
			acc := SHR(acc, 1);
		END_IF
	END_FOR
END_FOR

Crc16 := acc;

(* Settings are assigned here rather than in a declaration initialiser. A value
   inside an existing structured initialiser cannot be changed from a script -
   the compiler goes on reading the stored structValue - and having them in code
   means Reopen can bring the port back up with different settings from an
   online session. *)
Settings.sPort			:= Port;
Settings.ulBaudrate		:= Baudrate;
Settings.byParity		:= Parity;
Settings.byStopBits		:= StopBits;
Settings.ulTimeout		:= 0;
Settings.ulBufferSize	:= 256;

IF ReplyTimeout > T#0S THEN
	THIS^.ReplyTimeout := ReplyTimeout;
END_IF
IF GapTime > T#0S THEN
	THIS^.GapTime := GapTime;
END_IF

(* Remember all of it, so Retune can wander off and RestoreTuning can come back
   without the caller repeating itself. Taken after the defaults above have been
   applied, so what is saved is what the port is actually running. *)
ConfiguredSettings		:= Settings;
ConfiguredReplyTimeout	:= THIS^.ReplyTimeout;
ConfiguredGapTime		:= THIS^.GapTime;

Configured := TRUE;

(* Re-open if the port was already up, so calling Init twice is not a silent
   no-op with the old settings still in force. *)
ReopenRequest := PortOpen;

(* One field at a time, which is what a sweep needs: everything not named here
   stays as Init configured it. Takes effect on the next Service, like Reopen. *)
IF NOT Configured THEN
	Retune := FALSE;
	RETURN;
END_IF

IF Baudrate > 0 THEN
	Settings.ulBaudrate := Baudrate;
END_IF
IF StopBitsRaw <> 255 THEN
	Settings.byStopBits := StopBitsRaw;
END_IF
IF ReplyTimeout > T#0S THEN
	THIS^.ReplyTimeout := ReplyTimeout;
END_IF
IF GapTime > T#0S THEN
	THIS^.GapTime := GapTime;
END_IF

Reopen();
Retune := TRUE;

(* Whatever a sweep did to Settings, this is the way back. Reopen rather than an
   immediate close: the port is only ever touched from Service, so that a caller
   cannot pull the bus out from under a frame in flight. *)
IF NOT Configured THEN
	RETURN;
END_IF

Settings		:= ConfiguredSettings;
ReplyTimeout	:= ConfiguredReplyTimeout;
GapTime			:= ConfiguredGapTime;

Reopen();

dwVar := SHL(WORD_TO_DWORD(wHi),16) OR WORD_TO_DWORD(wLo);
pt_REAL := ADR(dwVar);
SwapWordsToReal := pt_REAL^;

