(* FB_DO_COVER_001 keeps the relays it always had. The position-capable block gets DO_005 and DO_006, freed in HVAC_RUN for exactly this - two LEDs on the second output module that can be watched while the cover is commanded from Home Assistant, which is what makes the position logic verifiable at a glance.
One writer per coil, in one task. DO_005..DO_008 used to be written from HvacTask, and a second writer here would have made both meaningless without the compiler saying a word. *) FB_DO_COVER_001( TOGGLE:=FB_DI_PB_001.P_LONG, MU=>DO_003, MD=>DO_004 );
FB_DO_COVER_002( T_TravelUp := T#20S, T_TravelDown := T#20S, MU => DO_005, MD => DO_006 );

(* MQTT wiring no longer lives here.
Every block that extends FB_MQTT_BASE now wires itself from MqttVariables on its first cyclic call and announces itself to Home Assistant, driven by the FriendlyName set on its declaration above. What remains in this action is the behavioural configuration that genuinely is per-instance and is not MQTT, which is now only the dimmer's timings.
The one exception is FB_DI_PB_002: FB_INPUT_PUSHBUTTON_DIMMER_MQTT does not extend FB_MQTT_BASE, so it cannot self-wire yet and keeps its explicit call. *)
FB_DI_PB_002.InitMqtt( MQTTPublishPrefix:= ADR(MqttVariables.MqttPushbuttonPrefix), pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue), TRUE, (* specify whether dimmer value should be outputted on MQTT topic *) MQTT.QoS.ExactlyOnce, (* specify the QoS for the dimmer mqtt events (values 0-255) *) 5 (* specify the resolution for the dimmer mqtt events *) );
(* ALTER THE DIMMER OUTPUT DEFAULT BEHAVIOR *) FB_AO_DIMMER_001.ConfigureFunctionBlock( T_Debounce:=T#10MS, T_Reconfig:=T#10S, T_On_Max:=T#0S, T_Dimm_Start:=T#400MS, T_Dimm:=T#3S, Min_On:=50, Max_On:=255, Soft_Dimm:=TRUE, Rst_Out:=FALSE, OUT_LinearScaleMin:=11000, OUT_LinearScaleMax:=32767 );
(* Cover timings now travel through FB_init at the instance declaration. *)
(* DALI *) (* FB_DALI_1_ADR0.InitMqtt(MQTTPublishPrefix:= ADR(MqttVariables.MqttPubDimmerPrefix), MQTTSubscribePrefix:= ADR(MqttVariables.MqttSubDimmerPrefix), pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue), pMqttCallbackCollector := ADR(MqttVariables.collector_FB_DIMMER_MQTT) );
FB_DALI_1_ADR0.InitMqttDiscovery(ADR(MqttVariables.PLC_Device), 'Keuken'); *)
MqttVariables.PLC_Device.SendLogMessage('Init finished', 'MAIN_INIT');

FB_DO_BIN_001(OUT	=>		DO_001,										(* couple the function block to the physical output *)
	PRIO_HIGH				:=FALSE,  									(* brings the output high regardless of other input values *)
	PRIO_LOW				:=FALSE, 									(* brings the output low regardless of other input values. NOTE: PRIO_HIGH overrules PRIO_LOW input *)
	TOGGLE					:=FB_DI_PB_001.SINGLE 						(* for toggling the output *)	
);

FB_AO_DIMMER_001(
	SINGLE:=FB_DI_PB_001.SINGLE,
	LONG:=FB_DI_PB_001.LONG, 
	P_LONG:=FB_DI_PB_001.P_LONG, 
	Q_OUT => TestOUT,
	SET:=  FB_DI_PB_001.DOUBLE,
	VAL:=125
);

FB_DO_BISTABLE_001();

// Run the master before anything else
(*
M1_DALIMASTER(
	bPortDALI:=1,
	I_Port:=IoConfig_Globals.DALI_MULTI_MASTER_MODULE);

// Run individual DALI FB
FB_DALI_1_ADR0(
	BALLAST := DALIVariables.M1_Light1,
	TOGGLE := FB_DI_PB_002.SINGLE,
	P_LONG := FB_DI_PB_002.P_LONG,
	STATUS_LED => DO_002);
	*)

IF init = FALSE THEN
	init := TRUE;
	//https://art-net.org.uk/how-it-works/streaming-packets/artdmx-packet-definition/
	(* Write DMX header character in the buffer *) 
	S_BUF1.BUFFER [0]:= BYTE#16#41; // A
	S_BUF1.BUFFER [1]:= BYTE#16#72; // R	
	S_BUF1.BUFFER [2]:= BYTE#16#74; // T
	S_BUF1.BUFFER [3]:= BYTE#16#2D; // -
	S_BUF1.BUFFER [4]:= BYTE#16#4E; // N
	S_BUF1.BUFFER [5]:= BYTE#16#65; // E
	S_BUF1.BUFFER [6]:= BYTE#16#74; // T
	S_BUF1.BUFFER [7]:= BYTE#16#00; // 0 zero

	S_BUF1.BUFFER [8]:= BYTE#16#00;	// Opcode ArtDMX (0x5000) little endian
	S_BUF1.BUFFER [9]:= BYTE#16#50; // Opcode ArtDMX (0x5000) little endian

	S_BUF1.BUFFER [10]:= BYTE#16#00; // Protocol Version Hi (0)
	S_BUF1.BUFFER [11]:= BYTE#16#0E; // Protocol Version Lo (14)

	S_BUF1.BUFFER [12]:= BYTE#16#00; // Sequence
	S_BUF1.BUFFER [13]:= BYTE#16#00; // Physical

	S_BUF1.BUFFER [16]:= BYTE#16#02; // Length Hi
	S_BUF1.BUFFER [17]:= BYTE#16#00; // Length Lo (2 to 512, even)
	(* the DMX channels that are next have already been written to the buffer *) 

	IF Universe = 1 THEN
		S_BUF1.BUFFER [14]:= BYTE#16#01; // Universe little endian
		S_BUF1.BUFFER [15]:= BYTE#16#00; // Universe little endian
	END_IF
	IF Universe = 2 THEN
		S_BUF1.BUFFER [14]:= BYTE#16#02; // Universe little endian
		S_BUF1.BUFFER [15]:= BYTE#16#00; // Universe little endian
	END_IF
END_IF;


size := 512+18;
FOR i:= 0 TO 511 DO (* check whether the DMX values ​​in the global variable have changed *)
	// i+2 is strange, buffers are not the same, its often offset with 2 sometimes by 1, todo
	IF S_BUF1.BUFFER[i+18] <> DMXVariables.DMX.BUFFER[i+2] THEN
   		S_BUF1.BUFFER[i+18]:= DMXVariables.DMX.BUFFER[i+2];
		Step := 1;
	END_IF
END_FOR



ErrorTrig(CLK := IP_C.ERROR <> 0);

CASE Step OF
	0:
		//passive

	1:
		IP_C.C_MODE := 1; (* Mode: UDP+ACTIVE+Port+IP *)
		IP_C.C_ENABLE := TRUE; (* Release connection *)
		IP_C.TIME_RESET := TRUE; (*Reset TIME monitoring * *)
		IP_C.R_OBSERVE := TRUE; (* Monitor data receive *)
		R_BUF1.SIZE:= 0; (* Reset Home length *)
		IP_C.C_IP:= oscat_network.IP4_DECODE (DMXVariables.IP);
		IP_C.C_PORT:= WORD#6454;

		S_BUF1.SIZE := size;
		Step:=2;

	2:
		IP_CONTROL2 (TIME_OUT:= T#1S, IP_C:= IP_C, S_BUF:= S_BUF1, R_BUF:= R_BUF1);

		IF IP_C.ERROR <> 0  THEN
			Step:=666;
		END_IF
	666:		
     	PFC.SetLed(which:=PFC.LED.U3, how:=PFC.LedState.BLINK_RED);
		IF ErrorTrig.Q AND IP_C.ERROR = 33554432 THEN
		MqttVariables.PLC_Device.SendLogMessage(CONCAT('ERROR|DMX has a connection error ', DWORD_TO_STRING(IP_C.ERROR)));

		END_IF;

		error_send := TRUE;
		R_BUF1.SIZE := 0;
		IP_C.C_ENABLE:= FALSE; (* Enable connection establishment *) 
		IP_C.TIME_RESET:= FALSE;
		init:=FALSE;
		(* Leave the error state. Without this the branch re-ran every scan; init is
		   FALSE so the header is rebuilt, and the change-detect loop re-arms Step. *)
		Step := 0;
	ELSE
	  Step := 0;
END_CASE



// Check IP_C1.error
// 33554432 = 0x02000000
// Initialization of the socket interface failed (only WinNT).
// code = 0x 02 00 00 00 (hexadecimal)
//           !   !    ! 
//           !   !    Receive error 
//           !   Send error
//           Connect error

(* set user led green if connected to MQTT broker, flashing red if not *) IF MQTTConnectTrigger.Q THEN PFC.SetLed(which:=PFC.LED.U1, how:=PFC.LedState.STATIC_GRN); END_IF IF MQTTDisconnectTrigger.Q THEN PFC.SetLed(which:=PFC.LED.U1, how:=PFC.LedState.BLINK_RED); END_IF
(* allow the device to do its work *) MqttVariables.PLC_Device();
(* allow the rising edge detector to detect a connect/reconnect to the broker, used for birth message *) MQTTConnectTrigger(CLK := MQTTInfo.MQTT_CONNECTED);
(* allow the pulse generator to generate a pulse, used for birth message hartbeat *) MQTTBirthHartbeat(ENQ:=TRUE, PTH:=T#0S, PTL:=MqttVariables.MQTTAvailabilityHartbeatTime);
(* Check if this is a new connection due to startup or connection issues *) IF initMqtt AND (MQTTConnectTrigger.Q OR MQTTBirthHartbeat.Q) THEN MQTTPublishBirth := TRUE; END_IF
(* On connect or reconnect publish a birth message using the dedicated birth publisher *) IF MQTTPublishBirth THEN MQTTBirthPublisher.PublishMessage(MqttMessage := MQTTBirthMessage); MQTTPublishBirth:=FALSE; END_IF
(* Check if Mqtt is initialized AND if there are elements on the queue to process AND if a MQTTbirthmessage has been published successfully *) IF initMqtt AND MqttVariables.fbMqttPublishQueue.HasMessage() AND MQTTPublishBirth = FALSE AND MQTTBirthPublisher.SendDone THEN (* Loop through all free publishers untill there are no more elements in the queue or no more free publishers *) FOR i:=0 TO (ipublishers-1) DO (* use the publishers that are free *) IF publishers[i].SendDone AND MqttVariables.fbMqttPublishQueue.HasMessage() THEN (* Pass message from the queue to a publisher *) publishers[i].PublishMessage(MqttMessage:= MqttVariables.fbMqttPublishQueue.GetMessage()); ELSIF NOT MqttVariables.fbMqttPublishQueue.HasMessage() THEN (* Queue is empty, jump out of the for loop *) EXIT; END_IF END_FOR END_IF
(* If MQTT is initialized, let the MqttPublishWorkers do their work *) IF initMqtt THEN MQTT_IN_OUT.clientFB( MQTT_IN_OUT:= MQTT_IN_OUT, ENABLE:= TRUE, URL:= MQttVariables.broker, TIMEOUT:= T#1S, TLS:= FALSE);
MQTTBirthPublisher();
FOR i := 0 TO (ipublishers-1) DO publishers[i](); END_FOR
END_IF

IF NOT initMqtt THEN
	initMqtt := TRUE;
	(* Basic MQTT config *)
	MQTT_IN_OUT.ClientID := MqttVariables.clientID;

	(* Set the LWT topic / payload *)
	MQTT_IN_OUT.BuildWillTopicAndMessage := FALSE;
	MQTT_IN_OUT.WillTopicBase := '';
	MQTT_IN_OUT.ClientWillTopic := MqttVariables.MqttAvailabilityTopic;
	MQTT_IN_OUT.ClientWillMessage := MqttVariables.MqttAvailabilityOfflinePayload;

	(* Set the birth message *)
	MQTTBirthMessage.Payload := MqttVariables.MqttAvailabilityOnlinePayload;
	MQTTBirthMessage.Topic := MqttVariables.MqttAvailabilityTopic;
	MQTTBirthMessage.Qos := MqttVariables.MQTT_QOS_EXACTLY_ONCE;
	MQTTBirthMessage.MqttRetain := FALSE;

	(* Configure the rising/falling edge detector to detect a connect/reconnect to the broker, used for  birth message *)
	MQTTConnectTrigger(CLK := MQTTInfo.MQTT_CONNECTED);
	MQTTDisconnectTrigger(CLK := MQTTInfo.MQTT_CONNECTED);

	(* Configure the dedicated MQTTBirth publisher *)
	MQTTBirthPublisher.Init(inputMQTT_IN_OUT:= ADR(MQTT_IN_OUT));

	(* Configure the pulse generator for the birth message hartbeat *)
	 MQTTBirthHartbeat(ENQ:=TRUE, PTH:=T#0S, PTL:=MqttVariables.MQTTAvailabilityHartbeatTime);

	(* INIT MQTT PUBLISH STUFF *)
	FOR icounter := 0 TO (ipublishers-1) DO		
		publishers[icounter].Init(inputMQTT_IN_OUT:= ADR(MQTT_IN_OUT));
	END_FOR 

	(* INIT MQTT SUBSCRIBE STUFF *)
	subscriber_FB_OUTPUT_SWITCH_MQTT.SetMqttInOut(MQTT_IN_OUT:= MQTT_IN_OUT);	
	subscriber_FB_OUTPUT_COVER_MQTT.SetMqttInOut(MQTT_IN_OUT:= MQTT_IN_OUT);
	subscriber_FB_DIMMER_MQTT.SetMqttInOut(MQTT_IN_OUT:= MQTT_IN_OUT);
	subscriber_FB_RS485_MQTT.SetMqttInOut(MQTT_IN_OUT:= MQTT_IN_OUT);
	subscriber_FB_HVAC_MQTT.SetMqttInOut(MQTT_IN_OUT:= MQTT_IN_OUT);
END_IF

(* The thermostats, the pumps and the burner now wire and announce themselves from
   their FriendlyName, set where they are declared. What is left here is the one
   block a name cannot describe.

   FB_PUMP_2_COLLECTOR keeps BOTH of its calls, and they belong together: its
   discovery config carries eight separate valve names, so it cannot be driven from
   a single FriendlyName - and because InitMqttDiscovery does nothing until
   InitMqttDone is TRUE, moving only its wiring into the block would leave this
   discovery call running a cycle too early, silently announcing nothing. *)

IF NOT InitHvacDone THEN
	InitHvacDone := TRUE;

	FB_PUMP_2_COLLECTOR.InitMqtt(ADR(MqttVariables.MqttPubHVACPrefix), ADR(MqttVariables.fbMqttPublishQueue));
	CollectorValveNames[1] := 'Radiator 1';
	CollectorValveNames[2] := 'Radiator 2';
	FB_PUMP_2_COLLECTOR.InitMqttDiscovery(ADR(MqttVariables.PLC_Device), CollectorValveNames);
END_IF

// HVAC flow 1
// 1. A thermostat requests heat once:
// 		1.1 The measured temperature is below the target temperature (hysteresis possible)
//		1.2 The thermostat is in 'heat' mode (or auto mode)
//		1.3 The temperature sensor used in the thermostat is not in error
//		1.4 The measured temperature is not above the configured max temperature
// 2. The Thermostat connects to a heating Valve turning it on/open when heat is required
//		2.1 The heating valve takes X amount of time to switch fully open
//		2.2 The heating valve can only turn on the pump once it's fully open
// 		2.3 The heating valve can only start closing once the pump has completed its minimum cycle time
// 3. The Heating valve is part of PUMP circuit together with other valves:
//		3.1 The pump can only turn off if it has ran for its minimum cycle time
//		3.2 Whenever the pump is running it should request heat from the heating system
// 4. The heating system should provide heat from the moment one pump requires it
//		4.1 A system might have multiple pumps
//		4.2 The heating system might have a minimum cycle time 

// 1. A thermostat requests heat once:
// 		1.1 The measured temperature is below the target temperature (hysteresis possible)
//		1.2 The thermostat is in 'heat' mode (or auto mode)
//		1.3 The temperature sensor used in the thermostat is not in error
//		1.4 The measured temperature is not above the configured max temperature
// 2. The Thermostat connects to a pump turning it on when heat is required
//		2.1 The pump can only turn off if it has ran for its minimum cycle time
//		2.2 Whenever the pump is running it should request heat from the heating system
// 3. The heating system should provide heat from the moment one pump requires it
//		3.1 A system might have multiple pumps
//		3.2 The heating system might have a minimum cycle time 


// FLoorheating
FB_THERMOSTAT_1(MEASURED_TEMP := RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.TEMPERATURE, MEASURED_HUM := RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.HUMIDITY, SENSOR_VALID := RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.DataAvailable AND NOT RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.Error);
FB_PUMP_1(
	IN := FB_THERMOSTAT_1.OUT
	(* Coil dropped: DO_005..DO_008 are the bench's spare LEDs now, and the
	   cover block uses two of them. The pump logic and its MQTT entity are
	   untouched - only the physical output is gone. *)
);


// Radiators
FB_THERMOSTAT_2(MEASURED_TEMP := RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.TEMPERATURE, MEASURED_HUM := RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.HUMIDITY, SENSOR_VALID := RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.DataAvailable AND NOT RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.Error);
FB_THERMOSTAT_3(MEASURED_TEMP := RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.TEMPERATURE, MEASURED_HUM := RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.HUMIDITY, SENSOR_VALID := RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.DataAvailable AND NOT RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.Error);

(* Circuit 1 is Radiator 1, circuit 2 is Radiator 2; circuits 3..8 are unwired and
   their valves stay closed. The indices match CollectorValveNames above and the
   VALVE_n names published to MQTT. *)
FB_PUMP_2_COLLECTOR.THERMOSTAT[1] := FB_THERMOSTAT_2.OUT;
FB_PUMP_2_COLLECTOR.THERMOSTAT[2] := FB_THERMOSTAT_3.OUT;

FB_PUMP_2_COLLECTOR();


FB_PUMP_2(
	IN := FB_PUMP_2_COLLECTOR.PUMP
);

// Heat source for both pumps
FB_BURNER_GAS(
	IN := FB_PUMP_2.HEAT_REQUEST OR FB_PUMP_1.HEAT_REQUEST,
	//OUT => DO_013
);

IF NOT InitRS485 THEN
	InitRS485 := TRUE;

(* THE WIRE.
   COM1 is the only port the PFC200 runtime exposes - COM2, COM3 and COM4 were
   all tried and none of them opens. The port must also have been put into RS485
   mode once per controller with `serialmode RS485` from the CODESYS PLC shell.
   That is a commissioning step: no IEC code can do it, it survives a reboot,
   and until it is done the bus is silent with no error to show for it. *)
RS485Transport.Init(
	Port			:= SysCom.SYS_COM_PORTS.SYS_COMPORT1,
	Baudrate		:= BUS_BAUDRATE,
	Parity			:= SysCom.SYS_COM_PARITY.SYS_NOPARITY,
	StopBits		:= SysCom.SYS_COM_STOPBITS.SYS_ONESTOPBIT,
	ReplyTimeout	:= T#1S,			(* nothing at all by now means no reply *)
	GapTime			:= T#50MS			(* quiet line ends a frame *)
);

(* WHO GETS IT.
   Registration order no longer decides who is served first: selection resumes
   at a cursor and wraps, so the device registered last is polled as often as
   the device registered first. *)
RS485BusController.Init(
	Transport		:= RS485Transport,
	StartupDelay	:= T#5S,			(* let the slaves finish booting *)
	SilenceTime		:= T#50MS,			(* between frames, and between transactions *)
	StepTimeout		:= T#3S				(* watchdog on the transport, not on the slave *)
);

RS485BusController.RegisterDevice(device := RS485Variables.FB_RS485_EASTRON_SDM220_1);
RS485BusController.RegisterDevice(device := RS485Variables.FB_RS485_EASTRON_SDM630_1);
//RS485BusController.RegisterDevice(device := RS485Variables.FB_RS485_DUCO_DUCOBOX_HOME);
//RS485BusController.RegisterDevice(device := RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01);
RS485BusController.RegisterDevice(device := RS485Variables.FB_RS485_EASTRON_SDM_POWER_1);
RS485BusController.RegisterDevice(device := RS485Variables.FB_RS485_SEN0492_1);

(* WHAT CANNOT BE SPOKEN TO YET.
   Asked of every device registered above, before the bus controller is allowed to
   start. Nothing here names a device or a register: what has to be written, and
   where, is each device's own answer - see RS485Device.GetCommissioning. A device
   that needs nothing costs one method call.

   It holds the bus off while it runs, because a device being hunted for at some
   other baud rate makes the whole pair unusable for as long as that takes. *)
RS485Commissioner.Init(
	Transport			:= RS485Transport,
	pController			:= ADR(RS485BusController),
	BusBaudrate			:= BUS_BAUDRATE,
	pMqttPublishQueue	:= ADR(MqttVariables.fbMqttPublishQueue),
	MqttPublishPrefix	:= ADR(MqttVariables.MqttPubRS485Prefix),
	Enable				:= RS485Variables.RS485_COMMISSION_ON_BOOT
);

(* INIT RS485 DEVICE STUFF.
   Nothing to do for the three Eastron meters. Modbus address, poll rate and -
   for the SDM_POWER block - the meter model all reach them through FB_init at
   their declaration in RS485Variables, and FriendlyName wires up MQTT and Home
   Assistant on the first cyclic call. Registration above is the whole of it. *)

RS485Variables.FB_RS485_DUCO_DUCOBOX_HOME.InitRS485(
	DataPollingInterval := T#3S,		(* Polling interval for data array *)
	DeviceAddress := 3					(* Device address of the modbus device *)
);

// Nodes: valves for example
RS485Variables.FB_RS485_DUCO_DUCOBOX_HOME.AddNode(
	DataPollingInterval := T#15S
);
RS485Variables.FB_RS485_DUCO_DUCOBOX_HOME.AddNode(
	DataPollingInterval := T#15S
);

RS485Variables.FB_RS485_DUCO_DUCOBOX_HOME.InitMqtt(
	MQTTPublishPrefix:= ADR(MqttVariables.MqttPubRS485Prefix),
	MQTTSubscribePrefix:= ADR(MqttVariables.MqttSubRS485Prefix),
	pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue),
	pMqttCallbackCollector := ADR(MqttVariables.collector_FB_RS485_MQTT)
);


RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.InitMqtt(
	MQTTPublishPrefix:= ADR(MqttVariables.MqttPubRS485Prefix),
	pMqttPublishQueue := ADR(MqttVariables.fbMqttPublishQueue)
);
RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01.InitMqttDiscovery(
	Device := ADR(MqttVariables.OWD_MULTISENSOR_01),
	ParentDevice:= ADR(MqttVariables.PLC_Device),
	DeviceName := 'Lab PLC 1-Wire sensorhub',
	SupportsTemperature := TRUE,
	SupportsHumidity := TRUE,
	SupportsDewPoint := TRUE,
	SupportsOwdVoltage := TRUE);


END_IF

(* Commissioning owns the bus while it runs, so the scheduler is held off until it
   is finished - a device being hunted for at another baud rate makes the pair
   unusable for anything else. With nothing to commission it finishes on its first
   cycle, and this costs one comparison from then on.

   Neither call knows what is on the bus: the commissioner asks every registered
   device whether it needs anything (RS485Device.GetCommissioning), and the bus
   controller asks every registered device whether it wants the bus (HasWork). *)
IF NOT RS485Commissioner.Done THEN
	RS485Commissioner();
ELSE
	(* The bus controller drives the transport - it calls Service every cycle, which
	   is what opens and re-opens the serial port as well as carrying frames - so
	   there is nothing to do here but call it. *)
	RS485BusController();
END_IF

(* --- bus health, published where it can actually be read -----------------------
   The transport's counters are the only instrument this bus has, and reading
   them has meant an online debug session - the least reliable thing in the
   chain on this hardware. Published every thirty seconds instead, retained, so
   the answer to "is the bus healthy" is a topic rather than an expedition.

   The pair that matters is CrcFail against NoReply. Bytes that arrive and never
   frame are a different fault from no bytes at all: the first is framing or
   noise, the second is a device that did not answer. Everything else here is
   context for those two. *)
DiagTimer(IN := NOT DiagTimer.Q, PT := T#30S);
IF DiagTimer.Q THEN
	DiagReport := CONCAT('ok=', UDINT_TO_STRING(RS485Transport.Ok));
	DiagReport := CONCAT(DiagReport, ' noreply=');
	DiagReport := CONCAT(DiagReport, UDINT_TO_STRING(RS485Transport.NoReply));
	DiagReport := CONCAT(DiagReport, ' crc=');
	DiagReport := CONCAT(DiagReport, UDINT_TO_STRING(RS485Transport.CrcFail));
	DiagReport := CONCAT(DiagReport, ' short=');
	DiagReport := CONCAT(DiagReport, UDINT_TO_STRING(RS485Transport.ShortFrame));
	DiagReport := CONCAT(DiagReport, ' badaddr=');
	DiagReport := CONCAT(DiagReport, UDINT_TO_STRING(RS485Transport.BadAddress));
	DiagReport := CONCAT(DiagReport, ' badfunc=');
	DiagReport := CONCAT(DiagReport, UDINT_TO_STRING(RS485Transport.BadFunction));
	DiagReport := CONCAT(DiagReport, ' exc=');
	DiagReport := CONCAT(DiagReport, UDINT_TO_STRING(RS485Transport.Exceptions));
	DiagReport := CONCAT(DiagReport, ' lead=');
	DiagReport := CONCAT(DiagReport, UDINT_TO_STRING(RS485Transport.LeadNulls));
	DiagReport := CONCAT(DiagReport, ' trail=');
	DiagReport := CONCAT(DiagReport, UDINT_TO_STRING(RS485Transport.TrailNulls));
	DiagReport := CONCAT(DiagReport, ' tx=');
	DiagReport := CONCAT(DiagReport, UDINT_TO_STRING(RS485BusController.Transactions));
	DiagReport := CONCAT(DiagReport, ' steps=');
	DiagReport := CONCAT(DiagReport, UDINT_TO_STRING(RS485BusController.StepsExecuted));
	DiagReport := CONCAT(DiagReport, ' fail=');
	DiagReport := CONCAT(DiagReport, UDINT_TO_STRING(RS485BusController.StepFailures));
	DiagReport := CONCAT(DiagReport, ' lastfail=dev');
	DiagReport := CONCAT(DiagReport, BYTE_TO_STRING(RS485Transport.LastFailAddr));
	DiagReport := CONCAT(DiagReport, '/fc');
	DiagReport := CONCAT(DiagReport, BYTE_TO_STRING(RS485Transport.LastFailFunc));
	DiagReport := CONCAT(DiagReport, '/n');
	DiagReport := CONCAT(DiagReport, UDINT_TO_STRING(RS485Transport.LastFailLen));
	DiagReport := CONCAT(DiagReport, ' [');
	DiagReport := CONCAT(DiagReport, RS485Transport.LastFailBytes);
	DiagReport := CONCAT(DiagReport, ']');

	MqttVariables.fbMqttPublishQueue.AddMessage(
		Payload := DiagReport,
		Topic := CONCAT(MqttVariables.MqttPubRS485Prefix, 'BUS_COUNTERS'),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE);
END_IF

(* RS485 devices. Called even while commissioning runs: their bodies only
   publish and self-wire, and the scheduler is the only thing that talks to the
   bus on their behalf. *)
RS485Variables.FB_RS485_EASTRON_SDM220_1();
RS485Variables.FB_RS485_DUCO_DUCOBOX_HOME();
RS485Variables.FB_RS485_1WIRE_MULTISENSOR_01();
RS485Variables.FB_RS485_EASTRON_SDM630_1();
RS485Variables.FB_RS485_EASTRON_SDM_POWER_1();
RS485Variables.FB_RS485_SEN0492_1();

(* Ping the DMX artNet node *)
DMXnodeReachable := SysSockPing(szIPAddress:=DMXVariables.IP, ulTimeout:=100, pulReplyTime:= ADR(PingTime));

IF DMXnodeReachable = 0 THEN
    PFC.SetLed(which:=PFC.LED.U3, how:=PFC.LedState.STATIC_GRN);
	IF DMXnodeReachable <> PreviousReachable THEN
		MqttVariables.PLC_Device.SendLogMessage('DMX ping OK');
	END_IF
ELSIF DMXnodeReachable = 5 THEN
     PFC.SetLed(which:=PFC.LED.U3, how:=PFC.LedState.BLINK_RED);
	IF DMXnodeReachable <> PreviousReachable THEN
		MqttVariables.PLC_Device.SendLogMessage('DMX ping Error');
	END_IF
END_IF

PreviousReachable := DMXnodeReachable;
